const DefaultType = {
  collapseBelow: '(number|string)',
  iconPlacement: 'string',
  menuPlacement: 'string',
  menuStrategy: 'string',
  moreText: '(string|boolean)',
  moreIcon: 'string',
  threshold: 'number'
