    display: flex;
    gap: var(--carousel-items-gap);
    width: 100%;
    padding-inline: var(--carousel-items-peek);
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x mandatory;
    scroll-padding-inline: var(--carousel-items-peek);
