  @each $color-name, $color-map in $theme-colors {
    .theme-#{$color-name} {
      @each $key, $value in $color-map {
        --theme-#{$key}: var(--#{$color-name}-#{$key});
      }
    }
  }

  @include generate-theme-reset();
}

