}

@use "../functions" as *;
@use "../mixins/tokens" as *;
@use "../mixins/transition" as *;

// stylelint-disable custom-property-no-missing-var-function
$prose-tokens: () !default;

// scss-docs-start prose-tokens
// stylelint-disable-next-line scss/dollar-variable-default
$prose-tokens: defaults(
  (
    --content-font-size: 1rem,
    --content-line-height: 1.5,
    --content-gap: calc(var(--content-font-size) * var(--content-line-height)),
    --heading-color: light-dark(var(--gray-900), var(--white)),
  ),
  $prose-tokens
);
// scss-docs-end prose-tokens
// stylelint-enable custom-property-no-missing-var-function

@layer content {
  .prose {
    @include tokens($prose-tokens);
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--content-gap);
    max-width: 1000px;
    margin-inline: auto;
    font-size: var(--content-font-size);
    line-height: var(--content-line-height);

    @media (width >= 1024px) {
      --content-font-size: var(--font-size-md);
      --content-line-height: 1.625;
      // --content-gap: calc(var(--content-font-size) * var(--content-line-height));
    }

    :where(p, ul, ol, dl, pre, table, blockquote):not(:where(.not-prose, .not-prose *)) {
      margin-block: 0;
    }

    :where(ul, ol):not([class], :where(.not-prose, .not-prose *)) li:not(:last-child) {
      margin-bottom: calc(var(--content-gap) / 4);
    }

    :where(li ul, li ol):not(:where(.not-prose, .not-prose *)) {
      margin-top: calc(var(--content-gap) / 4);
    }

    :where(hr):not(:where(.not-prose, .not-prose *)) {
      margin: calc(var(--content-gap) * 1.5) 0;
      border: 0;
      border-block-start: var(--border-width) solid var(--hr-border-color);
    }

    :where(h1, h2, h3, h4, h5, h6):not([class], :where(.not-prose, .not-prose *)) {
      margin-top: 0;
      margin-bottom: calc(var(--content-gap) / -2);
      font-weight: 500;
      line-height: 1.25;

      code {
        font-weight: 600;
        color: inherit;
      }
    }

    :where(h1, h2):not(:first-child, :where(.not-prose, .not-prose *)) {
      margin-top: calc(var(--content-gap) * .75);
    }

    :where(h3, h4, h5, h6):not(:first-child, :where(.not-prose, .not-prose *)) {
      margin-top: calc(var(--content-gap) * .5);
    }

    :where(h1):not(:where(.not-prose, .not-prose *)) {
      font-size: 2.25em;
      line-height: 1.1;
    }
    :where(h2):not(:where(.not-prose, .not-prose *)) {
      font-size: 1.75em;
    }
    :where(h3):not(:where(.not-prose, .not-prose *)) {
      font-size: 1.5em;
    }
    :where(h4):not(:where(.not-prose, .not-prose *)) {
      font-size: 1.25em;
    }
    :where(h5):not(:where(.not-prose, .not-prose *)) {
      font-size: 1.125em;
    }
    :where(h6):not(:where(.not-prose, .not-prose *)) {
      font-size: 1em;
    }

    :where(a:not([class])):not(:where(.not-prose, .not-prose *)) {
      color: var(--link-color);
      text-decoration: underline;
      text-decoration-color: color-mix(in srgb, var(--link-color) 25%, transparent);
      text-underline-offset: 4px;
      @include transition(.1s text-decoration-color ease-in-out);

      &:hover {
        color: var(--link-hover-color);
        text-decoration-color: var(--link-hover-color);
      }
    }

    :where(img):not(:where(.not-prose, .not-prose *)) {
      max-width: 100%;
    }

    :where(blockquote):not(:where(.not-prose, .not-prose *)) {
      padding-inline-start: calc(var(--content-gap) / 2);
      margin: 0;
      border-inline-start: 4px solid var(--border-color);
    }

    :where(table):not(:where(.not-prose, .not-prose *)) {
      width: 100%;
      border-spacing: 0;
      border-collapse: collapse;
    }

    :where(table:not([class])):not(:where(.not-prose, .not-prose *)) {
      td,
      th {
        padding: 6px 12px;
        text-align: inherit;
        border: 1px solid var(--border-color);
      }
    }

    :where(dt):not(:where(.not-prose, .not-prose *)) {
      font-weight: 500;
    }

    :where(video, img):not(:where(.not-prose, .not-prose *)) {
      max-width: 100%;
    }
  }
}

@use "../config" as *;
@use "../functions" as *;
@use "../mixins/border-radius" as *;
@use "../mixins/tokens" as *;

// stylelint-disable declaration-no-important, selector-no-qualifying-type, property-no-vendor-prefix

$type-tokens: () !default;
$reboot-kbd-tokens: () !default;
$reboot-mark-tokens: () !default;

// scss-docs-start type-tokens
// stylelint-disable-next-line scss/dollar-variable-default
$type-tokens: defaults(
  (
    --heading-margin-bottom: var(--spacer-2),
    --heading-font-family: null,
    --heading-font-style: null,
    --heading-line-height: 1.2,
    --paragraph-margin-bottom: var(--spacer),
    --legend-margin-bottom: var(--spacer-2),
    --legend-font-size: 1.5rem,
    --legend-font-weight: null,
    --list-padding-x: var(--spacer-7),
  ),
  $type-tokens
);
// scss-docs-end type-tokens

:root,
:host {
  @include tokens($type-tokens);
}

// scss-docs-start reboot-kbd-tokens
// stylelint-disable-next-line scss/dollar-variable-default
$reboot-kbd-tokens: defaults(
  (
    --kbd-padding-y: .125rem,
    --kbd-padding-x: var(--spacer-1),
    --kbd-font-size: var(--font-size-xs),
    --kbd-color: var(--bg-body),
    --kbd-bg: var(--fg-2),
    --kbd-border-radius: var(--radius-3),
  ),
  $reboot-kbd-tokens
);
// scss-docs-end reboot-kbd-tokens

// scss-docs-start reboot-mark-tokens
// stylelint-disable-next-line scss/dollar-variable-default
$reboot-mark-tokens: defaults(
  (
    --mark-padding: .1875em,
    --mark-color: var(--fg-body),
    --mark-bg: light-dark(var(--yellow-100), var(--yellow-900)),
  ),
  $reboot-mark-tokens
);
// scss-docs-end reboot-mark-tokens

@layer reboot {
  // Reboot
  //
  // Normalization of HTML elements, manually forked from Normalize.css to remove
  // styles targeting irrelevant browsers while applying new styles.
  //
  // Normalize is licensed MIT. https://github.com/necolas/normalize.css

  // Document
  //
  // Change from `box-sizing: content-box` so that `width` is not affected by `padding` or `border`.

  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  // Root
  //
  // Ability to the value of the root font sizes, affecting the value of `rem`.
  // null by default, thus nothing is generated.

  :root,
  :host {
    // Assume browser default font-size of 16px, or a user's preference
    accent-color: var(--primary-base);

    @if $enable-smooth-scroll {
      @media (prefers-reduced-motion: no-preference) {
        scroll-behavior: smooth;
      }
    }
  }

  // Reset iframe color-scheme
  //
  // If the color scheme of an iframe differs from parent document, iframe gets
  // an opaque canvas background appropriate (resulting in a white background
  // on the iframe when in a page with a dark color scheme).
  iframe {
    color-scheme: light dark;
    border: 0;
  }

  // Body
  //
  // 1. Remove the margin in all browsers.
  // 2. As a best practice, apply a default `background-color`.
  // 3. Prevent adjustments of font size after orientation changes in iOS.
  // 4. Change the default tap highlight to be completely transparent in iOS.

  // scss-docs-start reboot-body-rules
  body {
    margin: 0; // 1
    font-family: var(--body-font-family);
    font-size: var(--body-font-size);
    font-weight: var(--body-font-weight);
    line-height: var(--body-line-height);
    color: var(--fg-body);
    text-align: var(--body-text-align);
    background-color: var(--bg-body); // 2
    -webkit-text-size-adjust: 100%; // 3
    -webkit-tap-highlight-color: transparent; // 4
  }
  // scss-docs-end reboot-body-rules

  hr {
    margin: var(--hr-margin-y, var(--spacer)) 0;
    border: 0;
    border-block-start: var(--border-width) solid var(--hr-border-color);
  }

  // Typography
  //
  // 1. Remove top margins from headings
  //    By default, `<h1>`-`<h6>` all receive top and bottom margins. We nuke the top
  //    margin for easier control within type scales as it avoids margin collapsing.

  %heading {
    margin-top: 0; // 1
    margin-bottom: var(--heading-margin-bottom);
    font-family: var(--heading-font-family);
    font-style: var(--heading-font-style);
    font-weight: var(--heading-font-weight, var(--font-weight-medium));
    line-height: var(--heading-line-height);
    color: var(--heading-color);
  }

  h1,
  .h1 {
    @extend %heading;
    font-size: var(--font-size-3xl);
  }

  h2,
  .h2 {
    @extend %heading;
    font-size: var(--font-size-2xl);
  }

  h3,
  .h3 {
    @extend %heading;
    font-size: var(--font-size-xl);
  }

  h4,
  .h4 {
    @extend %heading;
    font-size: var(--font-size-lg);
  }

  h5,
  .h5 {
    @extend %heading;
    font-size: var(--font-size-md);
  }

  h6,
  .h6 {
    @extend %heading;
    font-size: var(--font-size-sm);
  }

  // Reset margins on paragraphs
  //
  // Similarly, the top margin on `<p>`s get reset. However, we also reset the
  // bottom margin to use `rem` units instead of `em`.

  p {
    margin-top: 0;
    margin-bottom: var(--paragraph-margin-bottom);
  }

  // Abbreviations
  //
  // 1. Add the correct text decoration in Chrome, Edge, Opera, and Safari.
  // 2. Add explicit cursor to indicate changed behavior.
  // 3. Prevent the text-decoration to be skipped.

  abbr[title] {
    text-decoration: underline dotted; // 1
    cursor: help; // 2
    text-decoration-skip-ink: none; // 3
  }

  // Builds on `abbr`
  .initialism {
    font-size: var(--initialism-font-size, var(--font-size-xs));
    text-transform: uppercase;
  }

  // Address

  address {
    margin-bottom: var(--spacer);
    font-style: normal;
    line-height: inherit;
  }

  // Lists

  ol,
  ul {
    padding-inline-start: var(--list-padding-x);
  }

  ol,
  ul,
  dl {
    margin-top: 0;
    margin-bottom: var(--spacer);
  }

  ol ol,
  ul ul,
  ol ul,
  ul ol {
    margin-bottom: 0;
  }

  dt {
    font-weight: var(--dt-font-weight, var(--font-weight-bold));
  }

  // 1. Undo browser default

  dd {
    margin-inline-start: 0; // 1
    margin-bottom: var(--spacer-2);
  }

  // Blockquote

  blockquote {
    margin: 0 0 var(--spacer);
    > * {
      margin-block: 0;
    }
  }

  // Strong
  //
  // Add the correct font weight in Chrome, Edge, and Safari

  b,
  strong {
    font-weight: var(--font-weight-bolder);
  }

  // Small
  //
  // Add the correct font size in all browsers

  small,
  .small {
    font-size: var(--small-font-size, 87.5%);
  }

  // Mark

  mark,
  .mark {
    @include tokens($reboot-mark-tokens);
    padding: var(--mark-padding);
    color: var(--mark-color);
    background-color: var(--mark-bg);
  }

  // Sub and Sup
  //
  // Prevent `sub` and `sup` elements from affecting the line height in
  // all browsers.

  sub,
  sup {
    position: relative;
    font-size: var(--sub-sup-font-size, .75em);
    line-height: 0;
    vertical-align: baseline;
  }

  sub { bottom: -.25em; }
  sup { top: -.5em; }

  // Links

  a {
    color: var(--theme-fg, var(--link-color));
    text-decoration: var(--link-decoration);
    text-underline-offset: var(--link-underline-offset);

    &:hover {
      color: var(--theme-fg-emphasis, var(--link-hover-color));
      text-decoration: var(--link-hover-decoration, var(--link-decoration));
    }
  }

  // And undo these styles for placeholder links/named anchors (without href).
  // It would be more straightforward to just use a[href] in previous block, but that
  // causes specificity issues in many other styles that are too complex to fix.
  // See https://github.com/twbs/bootstrap/issues/19402

  a:not([href], [class]) {
    &,
    &:hover {
      color: inherit;
      text-decoration: none;
    }
  }

  // Code

  pre,
  code,
  kbd,
  samp {
    font-family: var(--font-mono);
    font-size: 1em; // Correct the odd `em` font sizing in all browsers.
  }

  // 1. Remove browser default top margin
  // 2. Reset browser default of `1em` to use `rem`s
  // 3. Don't allow content to break outside
  // 4. Reserve room for the scrollbar so it cannot sit on top of the last line

  pre {
    display: block;
    margin-top: 0; // 1
    margin-bottom: var(--spacer); // 2
    overflow: auto; // 3
    font-size: var(--code-font-size);
    color: var(--code-color, inherit);
    scrollbar-gutter: stable; // 4

    // Account for some code outputs that place code tags in pre tags
    code {
      font-size: inherit;
      color: inherit;
      word-break: normal;
    }
  }

  code {
    font-size: var(--code-font-size);
    color: var(--code-color);
    word-wrap: break-word;

    // Streamline the style when inside anchors to avoid broken underline and more
    a > & {
      color: inherit;
    }
  }

  kbd {
    @include tokens($reboot-kbd-tokens);
    padding: var(--kbd-padding-y) var(--kbd-padding-x);
    font-size: var(--kbd-font-size);
    color: var(--kbd-color);
    background-color: var(--kbd-bg);
    @include border-radius(var(--kbd-border-radius));

    kbd {
      padding: 0;
      font-size: 1em;
    }
  }

  // Figures
  //
  // Apply a consistent margin strategy (matches our type styles).

  figure {
    margin: 0 0 var(--spacer);
  }

  // Images and content

  img,
  svg {
    vertical-align: middle;
  }

  // Tables
  //
  // Prevent double borders

  table {
    caption-side: bottom;
    border-collapse: collapse;
  }

  caption {
    padding-block: var(--spacer-2);
    color: var(--fg-3);
    text-align: start;
  }

  // 1. Matches default `<td>` alignment by inheriting `text-align`.
  // 2. Fix alignment for Safari

  th {
    text-align: inherit; // 1
    text-align: -webkit-match-parent; // 2
  }

  thead,
  tbody,
  tfoot,
  tr,
  td,
  th {
    border-color: inherit;
    border-style: solid;
    border-width: 0;
  }

  // Forms
  //
  // 1. Allow labels to use `margin` for spacing.

  label {
    display: inline-block; // 1
  }

  // Remove the default `border-radius` that macOS Chrome adds.
  // See https://github.com/twbs/bootstrap/issues/24093

  button {
    // stylelint-disable-next-line property-disallowed-list
    border-radius: 0;
  }

  // Explicitly remove focus outline in Chromium when it shouldn't be
  // visible (e.g. as result of mouse click or touch tap). It already
  // should be doing this automatically, but seems to currently be
  // confused and applies its very visible two-tone outline anyway.

  button:focus:not(:focus-visible) {
    outline: 0;
  }

  // 1. Remove the margin in Firefox and Safari

  input,
  button,
  select,
  optgroup,
  textarea {
    margin: 0; // 1
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
  }

  // Set the cursor for non-`<button>` buttons
  //
  // Details at https://github.com/twbs/bootstrap/pull/30562
  [role="button"] {
    cursor: pointer;
  }

  select {
    // Remove the inheritance of word-wrap in Safari.
    // See https://github.com/twbs/bootstrap/issues/24990
    word-wrap: normal;

    // Undo the opacity change from Chrome
    &:disabled {
      opacity: 1;
    }
  }

  // Remove the dropdown arrow only from text type inputs built with datalists in Chrome.
  // See https://stackoverflow.com/a/54997118

  [list]:not([type="date"], [type="datetime-local"], [type="month"], [type="week"], [type="time"])::-webkit-calendar-picker-indicator {
    display: none !important;
  }

