        color: var(--fg-3);
        cursor: default;
      }
    }
    &:disabled:checked {
      opacity: var(--check-disabled-opacity);
    }
  }

  .check-sm {
    --check-size: 1rem;

    + label {
      font-size: var(--font-size-sm);
    }
  }
  .check-lg {
    --check-size: 1.5rem;
    --check-margin-block: .375rem;

    + label {
      font-size: var(--font-size-lg);
    }
  }
}

