// scss-docs-end form-control-tokens

// scss-docs-start form-control-sizes
$form-control-sizes: () !default;
// stylelint-disable-next-line scss/dollar-variable-default
$form-control-sizes: defaults(
  ("sm", "lg"),
  $form-control-sizes
);
// scss-docs-end form-control-sizes
// stylelint-enable custom-property-no-missing-var-function

@layer forms {
  .form-control {
    @include tokens($form-control-tokens);

    display: flex;
    width: 100%;
    min-height: var(--control-min-height);
    padding: var(--control-padding-y) var(--control-padding-x);
    font-size: var(--control-font-size);
    line-height: var(--control-line-height);
    color: var(--control-fg);
    appearance: none;
    background-color: var(--control-bg);
    background-clip: padding-box;
    border: var(--control-border-width) solid var(--control-border-color);
    @include border-radius(var(--control-border-radius), 0);
    @include box-shadow(var(--control-box-shadow));
    @include transition-props(
      var(--control-transition-property),
      var(--control-transition-duration),
      var(--control-transition-timing)
    );

    // Customize the `:focus` state to imitate native WebKit styles.
    &:focus-visible,
    &:focus-within {
      --focus-ring-offset: -1px;
      @include focus-ring(true);
    }

    // Placeholder
    &::placeholder {
      color: var(--control-placeholder-color);
      // Override Firefox's unusual default opacity; see https://github.com/twbs/bootstrap/pull/11526.
      opacity: 1;
    }

    // Disabled inputs
    //
    // HTML5 says that controls under a fieldset > legend:first-child won't be
    // disabled if the fieldset is disabled. Due to implementation difficulty, we
    // don't honor that edge case; we style them as disabled anyway.
    &:disabled {
      color: var(--control-disabled-color);
      background-color: var(--control-disabled-bg);
      border-color: var(--control-disabled-border-color);
      // iOS fix for unreadable disabled content; see https://github.com/twbs/bootstrap/issues/11655.
      opacity: 1;
    }

    // Prevent excessive date input height in WebKit/Blink; see
    // https://github.com/twbs/bootstrap/issues/34433.
    &::-webkit-datetime-edit {
      display: block;
      padding: 0;
    }

    // Soften `/` and `:` separators between date/time fields (WebKit/Blink only).
    &::-webkit-datetime-edit-text {
      color: var(--control-placeholder-color);
    }

    // File inputs
    &[type="file"] {
      overflow: hidden; // prevent pseudo element button overlap

      &:not(:disabled, [readonly]) {
        cursor: pointer;
      }
    }
    &::file-selector-button {
      min-height: var(--control-min-height);
      padding: var(--control-padding-y) var(--control-padding-x);
      margin: calc(var(--control-padding-y) * -1) calc(var(--control-padding-x) * -1);
      margin-inline-end: var(--control-padding-x);
      color: var(--control-fg);
      // @include gradient-bg(var(--control-action-bg));
      pointer-events: none;
      background-color: var(--control-action-bg);
      border-color: inherit;
      border-style: solid;
      border-width: 0;
      border-inline-end-width: var(--control-border-width);
      border-radius: 0; // stylelint-disable-line property-disallowed-list
      @include transition-props(
        var(--control-transition-property),
        var(--control-transition-duration),
        var(--control-transition-timing)
      );
    }

    &:hover:not(:disabled, [readonly])::file-selector-button {
      background-color: var(--control-action-hover-bg);
    }
  }

  // Readonly controls as plain text
  //
  // Apply class to a readonly input to make it appear like regular plain
  // text (without any border, background color, focus indicator)

  .form-control-plaintext {
    // Plaintext is a standalone class (not combined with `.form-control`), so it
    // needs its own copy of the control tokens. Without them the `var(--control-*)`
    // references below are invalid and fall back to their initial values (e.g.
    // `border-width: medium`), which adds phantom inline borders and misaligns the
    // text from a floating label.
    @include tokens($form-control-tokens);

    display: block;
    width: 100%;
    padding: var(--control-padding-y) 0;
    margin-bottom: 0; // match inputs if this class comes on inputs with default margins
    line-height: var(--control-line-height);
    color: var(--control-fg);
    background-color: transparent;
    border: solid transparent;
    border-width: var(--control-border-width) 0;

    &:focus {
      outline: 0;
    }

    &.form-control-sm,
    &.form-control-lg {
      padding-inline: 0;
    }
  }

  // stylelint-disable selector-no-qualifying-type
  select.form-control,
  .form-control-caret {
    padding-inline-end: calc(var(--control-padding-x) * 3);
    background-image: var(--control-select-bg);
    background-repeat: no-repeat;
    background-position: var(--control-select-bg-position);
    background-size: var(--control-select-bg-size);

    &[multiple],
    &[size]:not([size="1"]) {
      padding-inline-end: var(--control-padding-x);
      background-image: none;
    }
  }

  [data-bs-theme="dark"] {
    select.form-control,
    .form-control-caret {
      background-image: var(--control-select-bg-dark);
    }
  }
  // stylelint-enable selector-no-qualifying-type

  // Form control sizing
  //
  // Build on `.form-control` with modifier classes to decrease or increase the
  // height and font-size of form controls.
  //
  // Repeated in `_input_group.scss` to avoid Sass extend issues.
  @each $size, $_ in $form-control-sizes {
    .form-control-#{$size} {
      --control-min-height: var(--btn-input-#{$size}-min-height);
      --control-padding-y: var(--btn-input-#{$size}-padding-y);
      --control-padding-x: var(--btn-input-#{$size}-padding-x);
      --control-font-size: var(--btn-input-#{$size}-font-size);
      --control-line-height: var(--btn-input-#{$size}-line-height);
      --control-border-radius: var(--btn-input-#{$size}-border-radius);
    }
  }

  .form-control-color {
    width: var(--control-min-height);
    padding: var(--control-padding-y);

    &:not(:disabled, [readonly]) {
      cursor: pointer;
    }

    &::-moz-color-swatch {
      border: 0 !important; // stylelint-disable-line declaration-no-important
      @include border-radius(var(--radius-5));
    }

    &::-webkit-color-swatch {
      border: 0 !important; // stylelint-disable-line declaration-no-important
      @include border-radius(var(--radius-5));
    }
  }

  // Ghost input - removes all visual styling
  // Used inside custom wrappers that handle their own styling
  .form-ghost {
    display: block;
    width: 100%;
    padding: 0;
    font: inherit;
    color: inherit;
    appearance: none;
    background: transparent;
    border: 0;

    &:focus {
      outline: 0;
    }

    &::placeholder {
      color: var(--fg-3);
      opacity: 1;
    }

    &:disabled {
      color: var(--fg-4);
      cursor: not-allowed;
    }
  }
}

@use "../mixins/border-radius" as *;

// scss-docs-start form-field
@layer forms {
  .form-field {
    position: relative;
    display: grid;
    gap: .5rem;
    // width: 100%;

    > label,
    > .form-label {
      justify-self: start;
      margin-bottom: 0;
    }

    &:has(> .check, > .radio, > .switch) {
      grid-template-columns: auto 1fr;
      column-gap: .5rem;
      align-items: start;

      > .check,
      > .radio,
      > .switch {
        grid-column: 1;
      }

      > :not(.check, .radio, .switch) {
        grid-column: 2;
      }

      > .form-label {
        grid-column: 1 / -1;
      }
    }
  }

  .form-field-content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
  }

  .form-field-card {
    position: relative;
    padding: calc(var(--spacer) * .75);
    cursor: pointer;
    border: var(--border-width) solid transparent;
    @include border-radius(var(--radius-7));

    &:hover {
      background-color: var(--bg-1);
    }

    &:has(:checked) {
      background-color: var(--bg-1);
      border-color: var(--border-color);
    }

    label::before {
      position: absolute;
      inset: 0;
      content: "";
    }
  }

  .form-group {
    display: grid;
    gap: .5rem;

    > label,
    > .form-label,
    > legend {
      justify-self: start;
      margin-bottom: 0;
    }
  }
}
