      > .form-control,
      > .input-group-text,
      > .btn {
        min-height: var(--btn-input-#{$size}-min-height);
        padding: var(--btn-input-#{$size}-padding-y) var(--btn-input-#{$size}-padding-x);
        font-size: var(--btn-input-#{$size}-font-size);
        @include border-radius(var(--btn-input-#{$size}-border-radius));
