    $first: list.nth($transition, 1);

    @if $first != null {
      // `none` force-disables a transition, so it must reach every reader. It
      // arrives bare or as `none !important`, hence the list test.
      @if $enable-reduced-motion and not list.index($first, none) {
        @media (prefers-reduced-motion: no-preference) {
          transition: $transition;
        }
      } @else {
        transition: $transition;
      }
    }
  }
}

// Set the `transition-*` properties one by one. In the shorthand a trailing
// duration binds to the last property only, so `color, box-shadow .15s` leaves
// `color` at `0s`. Set apart, one duration and easing cover every property.
//
// This also keeps the property list in a custom property. A single token then
// adds a property to the animation, where the shorthand would need the whole
// declaration again.
//
// Pass `$behavior: allow-discrete` for a list that animates a discrete
// property, such as `display` or `content-visibility`.
@mixin transition-props($property, $duration, $timing, $behavior: null) {
  @if $enable-transitions {
    @if $enable-reduced-motion {
      @media (prefers-reduced-motion: no-preference) {
        @include transition-longhands($property, $duration, $timing, $behavior);
      }
    } @else {
      @include transition-longhands($property, $duration, $timing, $behavior);
    }
  }
}

@mixin transition-longhands($property, $duration, $timing, $behavior) {
  transition-timing-function: $timing;
  transition-duration: $duration;
  transition-property: $property;

  @if $behavior {
    transition-behavior: $behavior;
  }
}

@use "sass:list";
@use "sass:map";
@use "sass:meta";
@use "sass:string";
@use "../layout/breakpoints" as bp;

// Utility generator

// - Utilities can use three different types of selectors:
//   - class: .class
//   - attr-starts: [class^="class"]
//   - attr-includes: [class*="class"]
// - Utilities can target children via `child-selector`, wrapped in :where() for zero specificity
// - Utilities can generate regular CSS properties and CSS custom properties
// - Utilities can be responsive or not
// - Utilities can have state variants (e.g., hover, focus, active)
// - Utilities can define local CSS variables
//
// CSS custom properties can be generated in two ways:
//
// 1. Property map with null values (CSS var receives the utility value):
// "bg-color": (
//   property: (
//     "--bg": null,
//     "background-color": var(--bg)
//   ),
//   class: bg,
//   values: (
//     primary: var(--blue-500),
//   )
// )
// Generates:
// .bg-primary {
//   --bs-bg: var(--bs-blue-500);
//   background-color: var(--bs-bg);
// }
//
// 2. Variables map (static CSS custom properties on every class):
// "link-underline": (
//   property: text-decoration-color,
//   class: link-underline,
//   variables: (
//     "link-underline-opacity": 1
//   ),
//   values: (...)
// )
// Generates:
// .link-underline {
//   --bs-link-underline-opacity: 1;
//   text-decoration-color: ...;
// }

// Helper mixin to emit CSS custom properties from a utility's `variables` key.
// When variables is a map, the provided static values are used on each class.
// When variables is a list or single identifier, each variable receives the current utility value.
@mixin generate-variables($utility, $value) {
  @if map.has-key($utility, variables) {
    $variables: map.get($utility, variables);
    @if meta.type-of($variables) == "map" {
      @each $var-key, $var-value in $variables {
        --#{$var-key}: #{$var-value};
      }
    } @else {
      // Treat as a list (or single identifier) — each variable gets the utility value
      @each $var-name in $variables {
        --#{$var-name}: #{$value};
      }
    }
  }
}

// Helper mixin to generate CSS properties for both legacy and property map approaches
@mixin generate-properties($utility, $property-map, $properties, $value) {
  @if $property-map != null {
    // Property-Value Mapping approach
    @each $property, $default-value in $property-map {
      // If value is a map, check if it has a key for this property.
      // Otherwise, use default-value (or $value if default-value is null).
      $actual-value: $default-value;
      @if meta.type-of($value) == "map" and map.has-key($value, $property) {
        $actual-value: map.get($value, $property);
      } @else if $default-value == null {
        $actual-value: $value;
      }
      @if map.get($utility, important) {
        #{$property}: $actual-value !important; // stylelint-disable-line declaration-no-important
      } @else {
        #{$property}: $actual-value;
      }
    }
  } @else {
    // Legacy approach
    @each $property in $properties {
      @if map.get($utility, important) {
        #{$property}: $value !important; // stylelint-disable-line declaration-no-important
      } @else {
        #{$property}: $value;
      }
    }
  }
}

@mixin generate-utility($utility, $prefix: "") {
  // Validate required keys
  @if not map.has-key($utility, property) {
    @error "Utility is missing required `property` key: #{$utility}";
  }
  @if not map.has-key($utility, values) {
    @error "Utility is missing required `values` key: #{$utility}";
  }

  // Warn on unknown keys (likely typos)
  $valid-keys: property, values, class, selector, responsive, print, dark, important, state, variables, child-selector, enabled;
  @each $key in map.keys($utility) {
    @if not list.index($valid-keys, $key) {
      @warn "Unknown utility key `#{$key}` found. Valid keys are: #{$valid-keys}";
    }
  }

  // Validate boolean keys
  @each $bool-key in (responsive, print, dark, important, enabled) {
    @if map.has-key($utility, $bool-key) {
      $val: map.get($utility, $bool-key);
      @if $val != true and $val != false {
        @error "Utility key `#{$bool-key}` should be a boolean (true or false), got: #{$val}";
      }
    }
  }

  // Determine if we're generating a class, or an attribute selector
  $selector-type: "class";
  @if map.has-key($utility, selector) {
    $selector-type: map.get($utility, selector);
    // Validate selector type
    $valid-selectors: "class", "attr-starts", "attr-includes";
    @if not list.index($valid-selectors, $selector-type) {
      @error "Invalid `selector` value `#{$selector-type}`. Must be one of: #{$valid-selectors}";
    }
  }
  // Then get the class name to use in a class (e.g., .class) or in an attribute selector (e.g., [class^="class"])
  $selector-class: map.get($utility, class);

  // Attribute selectors require a `class` key
  @if $selector-type != "class" and not map.has-key($utility, class) {
    @error "Utility with `selector: #{$selector-type}` requires a `class` key.";
  }

  // Get the list or map of values and ensure it's a map
  $values: map.get($utility, values);
  @if meta.type-of($values) != "map" {
    @if meta.type-of($values) == "list" {
      $list: ();
      @each $value in $values {
        $list: map.merge($list, ($value: $value));
      }
      $values: $list;
    } @else {
      $values: (null: $values);
    }
  }

  @each $key, $value in $values {
    $properties: map.get($utility, property);
    $property-map: null;
    $custom-class: "";

    // Check if property is a map (Property-Value Mapping approach)
    @if meta.type-of($properties) == "map" {
      $property-map: $properties;
      @if map.has-key($utility, class) {
        $custom-class: map.get($utility, class);
      }
    } @else {
      // Legacy approach: multiple properties are possible, for example with vertical or horizontal margins or paddings
      @if meta.type-of($properties) == "string" {
        $properties: list.append((), $properties);
      }
      // Use custom class if present, otherwise use the first value from the list of properties
      @if map.has-key($utility, class) {
        $custom-class: map.get($utility, class);
      } @else {
        $custom-class: list.nth($properties, 1);
      }
      @if $custom-class == null {
        $custom-class: "";
      }
    }

    // State params to generate state variants
    $state: ();
    @if map.has-key($utility, state) {
      $state: map.get($utility, state);
    }

    // Don't add a dash before value key if value key is null (e.g. with shadow class)
    $custom-class-modifier: "";
    @if $key {
      @if $custom-class == "" {
        $custom-class-modifier: $key;
      } @else {
        $custom-class-modifier: "-" + $key;
      }
    }

    // Build the class name fragment (without prefix or dot) for reuse in state variants
    $class-name: "";
    @if $selector-type == "class" {
      @if $custom-class != "" {
        $class-name: $custom-class + $custom-class-modifier;
      } @else if $selector-class != null and $selector-class != "" {
        $class-name: $selector-class + $custom-class-modifier;
      } @else {
        $class-name: $custom-class-modifier;
      }
    }

    $selector: "";
    @if $selector-type == "class" {
      $selector: ".#{$prefix + $class-name}";
    } @else if $selector-type == "attr-starts" {
      $selector: "[class^=\"#{$selector-class}\"]";
    } @else if $selector-type == "attr-includes" {
      $selector: "[class*=\"#{$selector-class}\"]";
    }

    // Apply child-selector wrapping if present (wraps in :where() for zero specificity)
    $child-sel: null;
    @if map.has-key($utility, child-selector) {
      $child-sel: map.get($utility, child-selector);
    }

    $final-selector: $selector;
    @if $child-sel {
      $final-selector: ":where(#{$selector} #{$child-sel})";
    }

    #{$final-selector} {
      @include generate-variables($utility, $value);
      @include generate-properties($utility, $property-map, $properties, $value);
    }

    // Generate state variants (e.g., hover:link-10 instead of link-10-hover)
    @if $state != () {
      @each $state-variant in $state {
        $state-selector: ".#{$prefix}#{$state-variant}\\:#{$class-name}:#{$state-variant}";
        @if $child-sel {
          $state-selector: ":where(#{$state-selector} #{$child-sel})";
        }

        #{$state-selector} {
          @include generate-variables($utility, $value);
          @include generate-properties($utility, $property-map, $properties, $value);
        }
      }
    }
  }
}

// Helper: append a custom property name to a list only if not already present.
@function append-unique-var($list, $name) {
  @if list.index($list, $name) == null {
    @return list.append($list, $name);
  }
  @return $list;
}

// Helper: collect custom property names (those starting with `--`) from a
// utility's `property` value, which may be a map, list, or string.
@function collect-property-vars($list, $properties) {
  @if meta.type-of($properties) == "map" {
    @each $prop, $value in $properties {
      @if meta.type-of($prop) == "string" and string.slice($prop, 1, 2) == "--" {
        $list: append-unique-var($list, $prop);
      }
    }
  } @else if meta.type-of($properties) == "list" {
    @each $prop in $properties {
      @if meta.type-of($prop) == "string" and string.slice($prop, 1, 2) == "--" {
        $list: append-unique-var($list, $prop);
      }
    }
  } @else if meta.type-of($properties) == "string" and string.slice($properties, 1, 2) == "--" {
    $list: append-unique-var($list, $properties);
  }
  @return $list;
}

// Registers every custom property that utilities assign to as non-inheriting
// via `@property`. Utilities compose values through local custom properties
// (e.g. `--bc`, `--bg`, `--fg`, `--rounded-size`); because custom properties
// inherit by default, setting one on an element would otherwise leak into every
// descendant (e.g. `.border-inverse` tinting nested component borders). Marking
// them `inherits: false` scopes each utility to the element it's applied to.
// `syntax: "*"` is used so no `initial-value` is required (values are complex
// expressions like `light-dark()` / `color-mix()` that can't be registered).
@mixin generate-utility-at-properties($utilities) {
  $names: ();

  @each $key, $utility in $utilities {
    @if meta.type-of($utility) == "map" and map.get($utility, enabled) != false {
      // Custom properties assigned via the `property` key
      $names: collect-property-vars($names, map.get($utility, property));

      // Custom properties assigned via the `variables` key (names lack the `--` prefix)
      @if map.has-key($utility, variables) {
        $variables: map.get($utility, variables);
        @if meta.type-of($variables) == "map" {
          @each $var-key, $var-value in $variables {
            $names: append-unique-var($names, "--" + $var-key);
          }
        } @else if meta.type-of($variables) == "list" {
          @each $var-name in $variables {
            $names: append-unique-var($names, "--" + $var-name);
          }
        } @else {
          $names: append-unique-var($names, "--" + $variables);
        }
      }
    }
  }

  @each $name in $names {
    @property #{$name} {
      syntax: "*";
      inherits: false;
    }
  }
}

// Generates all utility classes: base, responsive, print, and dark.
// Extracted so that tests can call this mixin directly with a custom $utilities map
// rather than having to mirror the loop conditions inline.
@mixin generate-utilities-loop($utilities, $breakpoints) {
  // Base + responsive (one pass per breakpoint)
  @each $breakpoint in map.keys($breakpoints) {
    @include bp.media-breakpoint-up($breakpoint, $breakpoints) {
      $prefix: bp.breakpoint-prefix($breakpoint, $breakpoints);

      @each $key, $utility in $utilities {
        @if meta.type-of($utility) == "map" and map.get($utility, enabled) != false and (map.get($utility, responsive) or $prefix == "") {
          @include generate-utility($utility, $prefix);
        }
      }
    }
  }

  // Print utilities
  @media print {
    @each $key, $utility in $utilities {
      @if meta.type-of($utility) == "map" and map.get($utility, enabled) != false and map.get($utility, print) == true {
        @include generate-utility($utility, "print\\:");
      }
    }
  }

  // Dark utilities
  @media (prefers-color-scheme: dark) {
    @each $key, $utility in $utilities {
      @if meta.type-of($utility) == "map" and map.get($utility, enabled) != false and map.get($utility, dark) == true {
        @include generate-utility($utility, "dark\\:");
      }
    }
  }
}

// stylelint-disable declaration-no-important

// Hide content visually while keeping it accessible to assistive technologies
//
// See: https://www.a11yproject.com/posts/2013-01-11-how-to-hide-content/
// See: https://kittygiraudel.com/2016/10/13/css-hide-and-seek/

@mixin visually-hidden() {
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important; // Fix for https://github.com/twbs/bootstrap/issues/25686
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;

  // Fix for positioned table caption that could become anonymous cells
  &:not(caption) {
    position: absolute !important;
  }

  // Fix to prevent overflowing children to become focusable
  * {
    overflow: hidden !important;
  }
}

// Use to only display content when it's focused, or one of its child elements is focused
// (i.e. when focus is within the element/container that the class was applied to)
//
// Useful for "Skip to main content" links; see https://www.w3.org/WAI/WCAG22/Techniques/general/G1.html

@mixin visually-hidden-focusable() {
  &:not(:focus, :focus-within) {
    @include visually-hidden();
  }
}

// Toggles
//
// Used in conjunction with global variables to enable certain theme features.

@forward "tokens";

// Deprecate
@forward "deprecate";

// Helpers
@forward "color-mode";
@forward "color-scheme";
@forward "image";
@forward "resize";
@forward "visually-hidden";
@forward "reset-text";
@forward "text-truncate";

// Utilities
@forward "utilities";

// Components
@forward "backdrop";
@forward "form-validation";
@forward "mask-icon";

// Skins
@forward "border-radius";
@forward "box-shadow";
@forward "gradients";
@forward "transition";

@use "sass:map";
@use "../config" as *;
@use "../mixins/utilities" as *;
@use "../utilities" as *;

// Register utility-composition custom properties as non-inheriting so utilities
// (e.g. `.border-inverse`) don't leak their composed value into descendants.
// Emitted outside the cascade layer since `@property` registration is global.
@include generate-utility-at-properties($utilities);

@layer utilities {
  @include generate-utilities-loop($utilities, $breakpoints);

  // The keyframe animation utilities (.animation-shake, .animation-pop) are
  // decorative, so disable them when the user prefers reduced motion.
  @if map.has-key($utilities, "animation") and $enable-reduced-motion {
    @media (prefers-reduced-motion: reduce) {
      .animation-shake,
      .animation-pop {
        animation: none;
      }
    }
  }
}

// Keyframes powering the animation utilities. Declared outside the cascade
// layer since @keyframes registration is global and unaffected by layers — which
// is also why they carry the utility prefix, so they cannot collide with a
// `shake` or `pop` animation of your own.
// Bundles such as `bootstrap-grid` narrow `$utilities` before importing this
// file, so skip the keyframes when the animation utility is filtered out.
@if map.has-key($utilities, "animation") {
  @keyframes animation-shake {
    10%,
    90% { transform: translate3d(-1px, 0, 0); }

    20%,
    80% { transform: translate3d(2px, 0, 0); }

    30%,
    50%,
    70% { transform: translate3d(-4px, 0, 0); }

    40%,
    60% { transform: translate3d(4px, 0, 0); }
  }

  // Scales from 0 to 1; the back-easing curve on the utility supplies the
  // slight overshoot, so the keyframes stay a simple two-stop scale.
  @keyframes animation-pop {
    from { transform: scale(0); }

    to { transform: scale(1); }
  }
}

---
title: Color
description: Bootstrap is supported by an extensive color system that powers our revamped theme, components, and color modes. This enables more comprehensive customization and extension for any project.
toc: true
---

import { getData } from '@libs/data'
import { getSequence } from '@libs/utils'

export const additionalColors = [
  'white',
  'black',
]

## Colors

There are 13 shades of 16 colors in Bootstrap’s new color system, meaning we have 208 colors to work with when using Bootstrap.

All Bootstrap colors are available as Sass variables and a Sass map in `scss/_config.scss` file. To avoid increased file sizes, we don’t create text or background color classes for each of these variables. Instead, we choose a subset of these colors for a [theme palette]([[docsref:/customize/theme]]).

Be sure to monitor contrast ratios as you customize colors. As shown below, we’ve added three contrast ratios to each of the main colors—one for the swatch’s current colors, one for against white, and one for against black.

<div class="grid bd-colors-grid">
  {getData('colors').map((color) => {
     return (
       <div class="d-contents grid-cols-fill">
         <h5 class="d-block text-capitalize grid-cols-fill">{color.name.replace('-', ' ')}</h5>

         {["025", "050", ...getSequence(100, 900, 100), 950, 975].map((value) => {
           return (
             <div class="mb-3 font-monospace small">
               <Swatch bg={`${color.name}-${value}`} size="medium" />
               <div class="text-center fg-3">{value}</div>
             </div>
           )
         })}
       </div>
     )
   })}

   <div class="d-contents grid-cols-fill">
    <h5 class="d-block text-capitalize grid-cols-fill">Additional</h5>
    {additionalColors.map((color) => {
      return (
        <div class="mb-3 font-monospace small">
          <Swatch bg={`${color}`} size="medium" />
          <div class="text-center fg-3">{color}</div>
        </div>
      )
    })}
   </div>
</div>

## How it works

Bootstrap generates its colors from a series of Sass variables and a Sass map called `$colors` in `scss/_colors.scss`. These are our base colors—blue, indigo, violet, etc—and are used to generate the tints and shades of each color you see above. You can customize these colors by adding or removing colors from the `$colors` map.

### Default colors

Below is our default list of colors. Colors are unique in Bootstrap in that they’re still Sass variables by default. In addition, they’re in `oklch()` format, which is a modern color space that is designed to be perceptually uniform.

<ScssDocs name="colors-list" file="scss/_colors.scss" />

The above colors are then turned into a Sass map called `$colors`.

<ScssDocs name="colors-map" file="scss/_colors.scss" />

### Color mixing

As mentioned already, we generate lighter (tints) and darker (shades) versions of each color using the `color-mix()` function. This allows us to quickly and easily generate a full scale of colors.

The tint and shade stops, the `color-mix()` color space, and the mix colors are all customizable.

<ScssDocs name="color-mix-options" file="scss/_colors.scss" />

Those options and the `$colors` map are used to generate a `$color-tokens` map, which is output as CSS custom properties on `:root`.

<ScssDocs name="color-tokens" file="scss/_colors.scss" />

In practice, our CSS variables that get output from this looks like this:

```scss
// Example generated custom properties from _colors.scss
--bs-blue-025: color-mix(in lab, var(--bs-white) 94%, oklch(60% 0.24 240));
--bs-blue-050: color-mix(in lab, var(--bs-white) 90%, oklch(60% 0.24 240));
--bs-blue-100: color-mix(in lab, var(--bs-white) 80%, oklch(60% 0.24 240));
// ...
--bs-blue-500: oklch(60% 0.24 240);
// ...
--bs-blue-900: color-mix(in lab, var(--bs-black) 64%, oklch(60% 0.24 240));
--bs-blue-975: color-mix(in lab, var(--bs-black) 88%, oklch(60% 0.24 240));
```

<Callout type="info">
We use CSS variables `var(--bs-white)` and `var(--bs-black)` to prevent LightningCSS from converting the real-time mixing into static `lab()` values. Unfortunately, this feature cannot be disabled in LightningCSS at this time.
</Callout>

## Customizing

You can customize the colors by adding or removing colors from the `$colors` map. You can also customize the tint and shade stops, the `color-mix()` color space, and the mix colors. Say you want to add another blue-gray color, like slate.

1. Create a new Sass variable for the new color, in `oklch()` format.
2. Add the new color to the `$colors` map.
3. Recompile source Sass to generate the new colors.

Here’s how that would look:

```scss
$slate: oklch(55% 0.07 260);

@use "bootstrap" as * with (
  $colors: (
    "slate": $slate,
  ),
);
```

To remove a color, set the value to `null`.

```scss
@use "bootstrap" as * with (
  $colors: (
    "pewter": null,
  ),
);
```

## From colors to theme

The `--bs-{color}-{stop}` tokens above are the raw palette. On their own they don’t style components—Bootstrap feeds a chosen subset of them into the **theme layer**, where they’re assigned semantic roles (background, foreground, border, and so on) and exposed as `.theme-*` classes that components read.

The full pipeline looks like this:

1. **`$colors`** (`scss/_colors.scss`) defines the base hues and generates the `--bs-{color}-{stop}` tokens (for example `--bs-blue-500`).
2. **`$theme-colors`** (`scss/_theme.scss`) maps semantic names (`primary`, `success`, `danger`, and so on) onto those tokens one role at a time (`base`, `fg`, `bg`, `bg-subtle`, `border`, `contrast`, …), most wrapped in `light-dark()` so they adapt to the color mode.
3. Those roles are emitted as **`--bs-{name}-{role}`** tokens (for example `--bs-primary-bg`).
4. The **`.theme-{name}`** classes remap them onto generic **`--bs-theme-{role}`** tokens (for example `.theme-primary` sets `--bs-theme-bg: var(--bs-primary-bg)`).
5. **Components** read the `--bs-theme-*` tokens, so a single `.theme-primary` class restyles any theme-aware component.

The theme layer—semantic tokens, `.theme-*` classes, layer colors, and color modes—is documented in full on the [Theme page]([[docsref:/customize/theme]]). The rest of this page stays on the base color layer.

## Generating utilities

Bootstrap doesn’t ship `color` and `background-color` utilities for every palette token—that would add a lot of rarely used CSS. If you need a few specific shades as utilities, add a utility group through the [utilities API]([[docsref:/utilities/api]]). Configure the `$utilities` map when you import `utilities`, then load `utilities/api` to emit the CSS. Each value points at a generated color token (`--bs-{color}-{stop}`):

```scss
@use "../node_modules/bootstrap/scss/utilities" with (
  $utilities: (
    "fg-palette": (
      property: color,
      class: fg,
      values: (
        "purple-300": var(--bs-purple-300),
        "purple-500": var(--bs-purple-500),
        "purple-700": var(--bs-purple-700),
      ),
    ),
  )
);
@use "../node_modules/bootstrap/scss/utilities/api";
```

This adds `.fg-purple-300`, `.fg-purple-500`, and `.fg-purple-700`. Bootstrap merges your entry on top of the default `$utilities` map, so the built-in utilities are left untouched. List as many shades as you need, and set `property: background-color` with `class: bg` to generate backgrounds instead. (The color tokens themselves come from your main Bootstrap import; this snippet only emits the extra utility classes.)

---
title: Optimize
description: Keep your projects lean, responsive, and maintainable so you can deliver the best experience and focus on more important jobs.
toc: true
---

## Lean Sass setup

When using Sass in your asset pipeline, make sure you optimize Bootstrap by only `@use`ing the partials you need. Your largest optimizations will likely come from the `Layout & Components` section of our `bootstrap.scss`.

<ScssDocs name="import-stack" file="scss/bootstrap.scss" />

If you’re not using a component, comment it out or delete its `@forward` entry entirely. For example, if you’re not using the carousel, remove that line to save file size in your compiled CSS. Keep in mind there are some dependencies across Sass partials that may make it more difficult to omit a file.

The cleanest way to do this is to maintain your own entry file that forwards only the parts of Bootstrap you need, rather than importing all of `bootstrap`. Copy the import stack above into your own stylesheet, then comment out the components you don’t use:

```scss
// custom-bootstrap.scss
@forward "bootstrap/scss/colors";
@forward "bootstrap/scss/root";

// Layout & content
@forward "bootstrap/scss/content";
@forward "bootstrap/scss/layout";
@forward "bootstrap/scss/forms";
@forward "bootstrap/scss/buttons";

// Components — keep only what you need
@forward "bootstrap/scss/alert";
@forward "bootstrap/scss/badge";
@forward "bootstrap/scss/card";
// @forward "bootstrap/scss/accordion";  // unused
// @forward "bootstrap/scss/carousel";   // unused
// @forward "bootstrap/scss/dialog";     // unused

// Helpers & utilities
@forward "bootstrap/scss/helpers";
@forward "bootstrap/scss/utilities/api";
```

Then compile your `custom-bootstrap.scss` instead of Bootstrap’s default `bootstrap.scss`. Just remember to keep `colors` and `root` (and any partials your remaining components depend on), since the rest of the framework builds on the variables and tokens they define.

## Lean JavaScript

Bootstrap’s JavaScript includes every component in our primary dist files (`bootstrap.js` and `bootstrap.min.js`), and even our primary dependencies (Floating UI and Vanilla Calendar Pro) with our bundle files (`bootstrap.bundle.js` and `bootstrap.bundle.min.js`). While you’re customizing via Sass, be sure to remove related JavaScript.

For instance, assuming you’re using your own JavaScript bundler like Webpack, Parcel, or Vite, you’d only import the JavaScript you plan on using. In the example below, we show how to just include our dialog JavaScript:

```js
// Import just what we need

// import 'bootstrap/js/dist/alert'
// import 'bootstrap/js/dist/button'
// import 'bootstrap/js/dist/carousel'
// import 'bootstrap/js/dist/collapse'
import 'bootstrap/js/dist/dialog'
// import 'bootstrap/js/dist/menu'
// import 'bootstrap/js/dist/drawer'
// import 'bootstrap/js/dist/popover'
// import 'bootstrap/js/dist/scrollspy'
// import 'bootstrap/js/dist/tab'
// import 'bootstrap/js/dist/toast'
// import 'bootstrap/js/dist/tooltip'
```

Importing a file this way runs it for its side effects, which registers that component’s data attribute API—so `data-bs-toggle` and friends keep working without any extra code. This way, you’re not including any JavaScript you don’t intend to use for components like buttons, carousels, and tooltips. If you’re importing menus, tooltips or popovers, be sure to list the Floating UI dependency in your `package.json` file. If you’re using the datepicker, be sure to also list the Vanilla Calendar Pro dependency.

<Callout>
**Heads up!** Files in `bootstrap/js/dist` use the **default export**. To use them, do the following:

```js
import Dialog from 'bootstrap/js/dist/dialog'
const dialog = new Dialog(document.getElementById('myDialog'))
```
</Callout>

## Autoprefixer .browserslistrc

Bootstrap depends on Autoprefixer to automatically add browser prefixes to certain CSS properties. Prefixes are dictated by our `.browserslistrc` file, found in the root of the Bootstrap repo and at the root of the npm package (`node_modules/bootstrap/.browserslistrc`). Customizing this list of browsers and recompiling the Sass will automatically remove some CSS from your compiled CSS, if there are vendor prefixes unique to that browser or version.

## Unused CSS

[PurgeCSS](https://github.com/FullHuman/purgecss) analyzes your markup and strips out any CSS selectors it can’t find in use, which can dramatically shrink Bootstrap’s compiled CSS. The setup below assumes a project of static HTML pages alongside Bootstrap’s JavaScript.

First, install PurgeCSS as a dev dependency:

```sh
npm install --save-dev purgecss
```

Then add a `purgecss.config.js` to the root of your project:

```js
// purgecss.config.js
export default {
  // Files to scan for the class names actually in use
  content: ['./**/*.html', './**/*.js'],
  // Your compiled Bootstrap CSS (plus any of your own)
  css: ['./css/bootstrap.css'],
  output: './css/bootstrap.purged.css',
  // Bootstrap 6 uses ":" in class names (e.g. `md:d-none`, `hover:opacity-50`),
  // so the extractor must keep colons and slashes.
  defaultExtractor: content => content.match(/[\w-/:]+(?<!:)/g) || [],
  safelist: {
    // Classes added at runtime by Bootstrap's JS that never appear in your HTML
    standard: ['show', 'active', 'hiding', 'dialog-open'],
    // Keep component families that are generated or toggled dynamically
    greedy: [/^carousel/, /^menu/, /^drawer/, /^dialog/, /^tooltip/, /^popover/]
  }
}
```

Run it as part of your build, pointing PurgeCSS at the config:

```sh
npx purgecss --config purgecss.config.js
```

Then serve `bootstrap.purged.css` instead of the full file.

<Callout type="warning">
**Test thoroughly after purging.** Bootstrap toggles many classes with JavaScript (`.show`, `.active`, `.hiding`, and more) and generates others dynamically (carousels, menus, dialogs). Anything PurgeCSS can’t find in the files it scans will be removed, so use the `safelist` option to protect runtime classes and verify every interactive component still works.
</Callout>

For deeper walkthroughs, the community has written some helpful guides:

- [Remove unused CSS styles from Bootstrap using PurgeCSS](https://medium.com/dwarves-foundation/remove-unused-css-styles-from-bootstrap-using-purgecss-88395a2c5772)
- [Automatically remove unused CSS from Bootstrap or other frameworks](https://lukelowrey.com/automatically-removeunused-css-from-bootstrap-or-other-frameworks/)
- [CSS-Tricks: How do you remove unused CSS from a site?](https://css-tricks.com/how-do-you-remove-unused-css-from-a-site/)

## Minify and gzip

Whenever possible, be sure to compress all the code you serve to your visitors. If you’re using Bootstrap dist files, try to stick to the minified versions (indicated by the `.min.css` and `.min.js` extensions). If you’re building Bootstrap from the source with your own build system, be sure to implement your own minifiers for HTML, CSS, and JS.

## Non-blocking files

While minifying and using compression might seem like enough, making your files non-blocking ones is also a big step in making your site well-optimized and fast enough.

If you are using a [Lighthouse](https://developer.chrome.com/docs/lighthouse/overview/) plugin in Google Chrome, you may have stumbled over FCP. [The First Contentful Paint](https://web.dev/articles/fcp) metric measures the time from when the page starts loading to when any part of the page’s content is rendered on the screen.

You can improve FCP by deferring non-critical JavaScript or CSS. What does that mean? Simply, JavaScript or stylesheets that don’t need to be present on the first paint of your page should be marked with `async` or `defer` attributes.

This ensures that the less important resources are loaded later and not blocking the first paint. On the other hand, critical resources can be included as inline scripts or styles.

If you want to learn more about this, there are already a lot of great articles about it:

- https://developer.chrome.com/docs/lighthouse/performance/render-blocking-resources/
- https://web.dev/articles/defer-non-critical-css

## Always use HTTPS

Your website should only be available over HTTPS connections in production. HTTPS improves the security, privacy, and availability of all sites, and there is no such thing as non-sensitive web traffic. The steps to configure your website to be served exclusively over HTTPS vary widely depending on your architecture and web hosting provider, and thus are beyond the scope of these docs.

Sites served over HTTPS should also access all stylesheets, scripts, and other assets over HTTPS connections. Otherwise, you’ll be sending users [mixed active content](https://developer.mozilla.org/en-US/docs/Web/Security/Mixed_content), leading to potential vulnerabilities where a site can be compromised by altering a dependency. This can lead to security issues and in-browser warnings displayed to users. Whether you’re getting Bootstrap from a CDN or serving it yourself, ensure that you only access it over HTTPS connections.

---
title: Sass
description: Utilize our source Sass files to take advantage of variables, maps, mixins, and functions to help you build faster and customize your project.
toc: true
---

## About Sass

[Sass](https://sass-lang.com/) is a CSS preprocessor that adds features like variables, nesting, mixins, and functions to standard CSS. You write `.scss` files, compile them, and the output is plain CSS that browsers understand. If you’re new to Sass, check out the [Sass documentation](https://sass-lang.com/guide/) to learn the basics.

Bootstrap is written in Sass. Our source `.scss` files use Sass maps to define design tokens, mixins to generate repetitive CSS patterns, and the `@use`/`@forward` module system to organize everything. When compiled, these Sass files produce the CSS that powers every Bootstrap component and utility. This lets you override token values, remove unused components, or extend the system with your own additions. If you don’t need that level of control, you can skip Sass entirely and [customize via CSS custom properties]([[docsref:/getting-started/css-variables]]) at runtime instead.

<Callout type="info">
**New to working with Sass and Bootstrap?** Start with [our npm guide]([[docsref:/guides/npm]]) for a step-by-step setup, or check out our [examples repository](https://github.com/twbs/examples) for ready-to-use starter projects.
</Callout>

## File structure

Whenever possible, avoid modifying Bootstrap’s core files. For Sass, that means creating your own stylesheet that imports Bootstrap so you can modify and extend it. Assuming you’re using a package manager like [npm](https://www.npmjs.com/) or [yarn](https://yarnpkg.com/), you’ll have a file structure that looks like this:

```text
your-project/
├── scss/
│   └── custom.scss
└── node_modules/
│   └── bootstrap/
│       ├── js/
│       └── scss/
└── index.html
```

If you’ve downloaded our source files and aren’t using a package manager, you’ll want to manually create something similar to that structure, keeping Bootstrap’s source files separate from your own.

```text
your-project/
├── scss/
│   └── custom.scss
├── bootstrap/
│   ├── js/
│   └── scss/
└── index.html
```

## Importing

In your `custom.scss`, you’ll import Bootstrap’s source Sass files. You have two options: include all of Bootstrap, or pick the parts you need. We encourage the latter, though be aware there are some requirements and dependencies across our components. You also will need to include some JavaScript for our plugins.

```scss
// Custom.scss
// Option A: Include all of Bootstrap

@use "../node_modules/bootstrap/scss/bootstrap";

// Then add additional custom code here
```

```scss
// Custom.scss
// Option B: Include parts of Bootstrap

// 1. Include root first (configuration, colors, tokens, and CSS layers)
@use "../node_modules/bootstrap/scss/root";

// 2. Include any other partials as needed
@use "../node_modules/bootstrap/scss/content";
@use "../node_modules/bootstrap/scss/layout";
@use "../node_modules/bootstrap/scss/forms";
@use "../node_modules/bootstrap/scss/buttons";

// 3. Components
@use "../node_modules/bootstrap/scss/alert";
@use "../node_modules/bootstrap/scss/card";
// ...

// 4. Helpers and utilities
@use "../node_modules/bootstrap/scss/helpers";
@use "../node_modules/bootstrap/scss/utilities/api";

// 5. Add additional custom code here
```

With that setup in place, you can begin to modify any of the Sass token maps in your `custom.scss`. We suggest using the full import stack from our `bootstrap.scss` file as your starting point.

<ScssDocs name="import-stack" file="scss/bootstrap.scss" />

## Compiling

In order to use your custom Sass code as CSS in the browser, you need a Sass compiler. Sass ships as a CLI package, but you can also compile it with other build tools like [Gulp](https://gulpjs.com/) or [Webpack](https://webpack.js.org/), or with GUI applications. Some IDEs also have Sass compilers built in or as downloadable extensions.

We like to use the CLI to compile our Sass, but you can use whichever method you prefer. From the command line, run the following:

```sh
# Install Sass globally
npm install -g sass

# Watch your custom Sass for changes and compile it to CSS
sass --watch ./scss/custom.scss ./css/custom.css
```

Learn more about your options at [sass-lang.com/install](https://sass-lang.com/install/) and [compiling with VS Code](https://code.visualstudio.com/docs/languages/css#_transpiling-sass-and-less-into-css).

<Callout>
**Using Bootstrap with another build tool?** Consider reading our guides for compiling with [Webpack]([[docsref:/guides/webpack]]), [Parcel]([[docsref:/guides/parcel]]), or [Vite]([[docsref:/guides/vite]]). We also have production-ready demos in [our examples repository on GitHub](https://github.com/twbs/examples).
</Callout>

## Including

Once your CSS is compiled, you can include it in your HTML files. Inside your `index.html` you’ll want to include your compiled CSS file. Be sure to update the path to your compiled CSS file if you’ve changed it.

```html
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Custom Bootstrap</title>
    <link href="/css/custom.css" rel="stylesheet"><!-- [!code highlight] -->
  </head>
  <body>
    <h1>Hello, world!</h1>
  </body>
</html>
```

## Token architecture

Bootstrap v6 uses a layered token system built on CSS custom properties. Sass maps define the tokens at compile time, and CSS custom properties are generated from those maps for runtime use.

The layers, from lowest to highest level:

1. **Color scales** (`_colors.scss`) — Base hue variables defined in `oklch()` generate a full scale of color steps (025–975) as CSS custom properties using `color-mix()`. For example, `--blue-500`, `--red-200`, `--gray-900`.

2. **Theme colors** (`_theme.scss`) — The `$theme-colors` map defines semantic color roles like `primary`, `success`, and `danger`. Each theme color is a nested map with sub-keys: `base`, `text`, `text-emphasis`, `bg`, `bg-subtle`, `bg-muted`, `border`, `focus-ring`, and `contrast`.

3. **Global tokens** (`_theme.scss` and `_root.scss`) — Semantic tokens for backgrounds (`$theme-bgs`), foregrounds (`$theme-fgs`), and borders (`$theme-borders`) are defined alongside the `$root-tokens` map, which aggregates everything into `:root` CSS custom properties.

4. **Component tokens** (e.g., `_alert.scss`) — Each component defines its own `$*-tokens` map (e.g., `$alert-tokens`) that gets output as CSS custom properties scoped to the component’s class.

## Token defaults

Every token map in Bootstrap includes the `!default` flag, allowing you to override values before Bootstrap’s files are loaded. Since Bootstrap uses Sass modules (`@use`/`@forward`), you can override `!default` variables using the `with ()` syntax. For CSS custom property tokens, you have two customization paths:

1. **At compile time** — Override the Sass maps that generate the CSS custom properties.
2. **At runtime** — Override the CSS custom properties directly in your stylesheet, no Sass required.

### Compile-time overrides

To override token values at compile time, use `@use ... with ()` when importing Bootstrap. You only need to include the keys you want to change — Bootstrap merges your overrides with its defaults using the `defaults()` function, so all other tokens remain intact.

```scss
@use "../node_modules/bootstrap/scss/bootstrap" with (
  $root-tokens: (
    --border-radius: .25rem,
    --spacer: 1.5rem,
  ),
  $alert-tokens: (
    --alert-padding-x: 2rem,
    --alert-border-radius: 1rem,
  )
);
```

Under the hood, every token map uses a two-step pattern:

```scss
$alert-tokens: () !default;
$alert-tokens: defaults(
  (
    // Default tokens here
  ),
  $alert-tokens
);
```

The `() !default` declaration receives your `with()` overrides. Then `defaults()` merges your entries on top of the built-in defaults, so unspecified keys keep their original values. Any keys set to `null` are removed from the map entirely, letting you drop tokens you don’t need.

### Runtime overrides

Because tokens are output as CSS custom properties, you can override them directly in CSS without any Sass compilation:

```css
:root {
  --border-radius: .25rem;
  --primary-base: oklch(55% 0.25 260);
  --bg-body: #f8f9fa;
}
```

You can also scope overrides to specific components:

```css
.alert {
  --alert-padding-x: 2rem;
  --alert-padding-y: 1.5rem;
  --alert-border-radius: 1rem;
}
```

<Callout name="info-npm-starter" />

## Maps and loops

Bootstrap includes several Sass maps that generate families of related CSS custom properties. These maps all include the `!default` flag and can be overridden.

### Theme color map

The `$theme-colors` map defines the semantic color palette. Each entry is a nested map with sub-keys like `base`, `text`, `bg`, `border`, and more. See the [Theme documentation]([[docsref:/customize/theme]]) for the full map, sub-key reference, and usage examples.

To add, modify, or remove theme colors at compile time, configure `$theme-colors` through the main entrypoint with `@use ... with ()`. `defaults()` merges your map on top of the built-ins, so the standard themes stay intact and you only add what you need:

```scss
@use "../node_modules/bootstrap/scss/bootstrap" with (
  $theme-colors: (
    "brand": (
      "base": var(--indigo-500),
      "fg": light-dark(var(--indigo-600), var(--indigo-400)),
      "fg-emphasis": light-dark(var(--indigo-800), var(--indigo-300)),
      "bg": var(--indigo-500),
      "bg-subtle": light-dark(var(--indigo-100), var(--indigo-900)),
      "bg-muted": light-dark(var(--indigo-200), var(--indigo-800)),
      "border": light-dark(var(--indigo-300), var(--indigo-600)),
      "focus-ring": light-dark(color-mix(in oklch, var(--indigo-500) 50%, var(--bg-body)), color-mix(in oklch, var(--indigo-500) 75%, var(--bg-body))),
      "contrast": var(--white)
    )
  )
);
```

<Callout type="warning">
Each theme color is a **nested** map, so the merge is one level deep. To change one sub-key of a built-in theme, pass the whole sub-map for that theme. A partial sub-map replaces the theme’s other sub-keys rather than merging with them. To remove a theme, set its key to `null`.
</Callout>

### Global token maps

Background (`$theme-bgs`), foreground (`$theme-fgs`), and border (`$theme-borders`) token maps define semantic layer colors. These are also covered in the [Theme documentation]([[docsref:/customize/theme#layer-colors]]).

### Root tokens (`$root-tokens`)

The `$root-tokens` map aggregates global design tokens like fonts, spacing, borders, and form variables. Theme colors, backgrounds, foregrounds, and border tokens are merged into it before output.

<ScssDocs name="root-tokens" file="scss/_root.scss" />

All root tokens are output to `:root` as CSS custom properties:

<ScssDocs name="root-theme-tokens" file="scss/_root.scss" />

## Component tokens

Each component defines its own token map that gets output as CSS custom properties scoped to the component’s class. This makes components self-contained and easy to customize.

Here’s the alert component as an example:

<ScssDocs name="alert-tokens" file="scss/_alert.scss" />

The tokens are output on the `.alert` class using the `tokens()` mixin:

```scss
.alert {
  @include tokens($alert-tokens);

  padding: var(--alert-padding-y) var(--alert-padding-x);
  color: var(--alert-color);
  background-color: var(--alert-bg);
  border: var(--alert-border);
  // ...
}
```

### Override Sass tokens

Use `with ()` to override specific component token values at compile time with Sass. Your overrides are merged with the defaults, so you only need to specify the keys you want to change:

```scss
@use "../node_modules/bootstrap/scss/bootstrap" with (
  $alert-tokens: (
    --alert-padding-x: 2rem,
    --alert-bg: var(--bg-2),
    --alert-border-radius: 0,
  )
);
```

This works for every component: `$card-tokens`, `$button-tokens`, `$menu-tokens`, `$nav-tokens`, and so on — any `$*-tokens` map supports partial overrides through the same merge pattern.

### Remove tokens with `null`

Set any map key to `null` to remove it entirely. The `defaults()` function strips null entries before the map is used, so no CSS is generated for those keys:

```scss
@use "../node_modules/bootstrap/scss/bootstrap" with (
  $alert-tokens: (
    --alert-margin-bottom: null,
  )
);
```

### Override CSS tokens

You can also override the CSS custom properties directly without Sass:

```css
.alert {
  --alert-padding-x: 2rem;
  --alert-bg: var(--bg-2);
  --alert-border-radius: 0;
}
```

## Size maps

In addition to token maps, Bootstrap uses size maps to generate size variant classes like `.btn-sm`, `.btn-lg`, `.form-control-sm`, etc. These use the same `defaults()` function and support the same override and removal patterns.

Size maps accept a simple list of size names:

```scss
$button-sizes: () !default;
$button-sizes: defaults(
  ("xs", "sm", "lg"),
  $button-sizes
);
```

The loop then derives CSS custom property values from each size name:

```scss
@each $size, $_ in $button-sizes {
  .btn-#{$size} {
    --btn-min-height: var(--btn-input-#{$size}-min-height);
    --btn-padding-y: var(--btn-input-#{$size}-padding-y);
    // ...
  }
}
```

To remove a size, set its key to `null` via `with()`:

```scss
@use "../node_modules/bootstrap/scss/bootstrap" with (
  $button-sizes: ("xs": null),
);
```

## Variant maps

Some components use variant maps to generate style variants. For example, `$button-variants` defines `solid`, `outline`, `subtle`, and `text` button styles. These are also processed by `defaults()` and support `null` removal:

```scss
@use "../node_modules/bootstrap/scss/bootstrap" with (
  $button-variants: (
    "text": null,
    "subtle": null,
  ),
);
```

This removes the `.btn-text` and `.btn-subtle` classes from the compiled CSS while keeping `.btn-solid` and `.btn-outline` intact.

## Required keys

Bootstrap assumes the presence of some specific keys within Sass maps as we use and extend these ourselves. As you customize the included maps, you may encounter errors where a specific Sass map’s key is being used.

For `$theme-colors`, the `primary`, `success`, and `danger` keys are required for links, buttons, and form states. Replacing the values of these keys should present no issues, but removing them may cause Sass compilation issues.

## Functions

### Defaults

The `defaults()` function is the backbone of Bootstrap’s customization system. It merges user overrides on top of built-in default tokens and strips any `null` entries from the result. Every token map, size map, and variant map uses it:

```scss
@function defaults($defaults, $overrides) { ... }
```

It accepts either a map or a list as the first argument. Lists are automatically converted to maps with `true` values, which is how size maps like `$button-sizes` work with a clean `("xs", "sm", "lg")` syntax.

`defaults()` are generated on specific selectors with the [`tokens()` mixin](#tokens).

### Color contrast

In order to meet the [Web Content Accessibility Guidelines (WCAG)](https://www.w3.org/TR/WCAG/) contrast requirements, authors **must** provide a minimum [text color contrast of 4.5:1](https://www.w3.org/TR/WCAG/#contrast-minimum) and a minimum [non-text color contrast of 3:1](https://www.w3.org/TR/WCAG/#non-text-contrast), with very few exceptions.

To help with this, we included the `color-contrast` function in Bootstrap. It uses the [WCAG contrast ratio algorithm](https://www.w3.org/TR/WCAG/#dfn-contrast-ratio) for calculating contrast thresholds based on [relative luminance](https://www.w3.org/TR/WCAG/#dfn-relative-luminance) in an `sRGB` color space to automatically return a light (`#fff`), dark (`#212529`) or black (`#000`) contrast color based on the specified base color. This function is especially useful for mixins or loops where you’re generating multiple classes.

For example, to generate color swatches from our `$theme-colors` map:

```scss
@each $color, $value in $theme-colors {
  .swatch-#{$color} {
    color: color-contrast(map.get($value, "base"));
  }
}
```

### Escape SVG

We use the `escape-svg` function to escape the `<`, `>` and `#` characters for SVG background images. When using the `escape-svg` function, data URIs must be quoted.

```scss
// Input — an inline SVG with special characters
$icon: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path fill='none' stroke='#00000080' stroke-width='2' d='m2 5 6 6 6-6'/></svg>");

// After escape-svg(), the <, >, and # characters are percent-encoded
// so the data URI works reliably in CSS (e.g. as a mask-image or background-image)
.element {
  mask-image: escape-svg($icon);
}
```

### Map helpers

We include several Sass functions for working with maps beyond what Sass provides natively.

<BsTable>
| Function | Description |
| --- | --- |
| `map-merge-multiple($maps...)` | Merges any number of maps into one, processing them left to right. |
| `map-get-multiple($map, $values)` | Returns a subset of a map filtered to only the keys listed in `$values`. |
| `map-get-nested($map, $nested-key)` | Extracts a single property from every nested map entry, returning a flat map. |
</BsTable>

#### `map-merge-multiple($maps...)`

```scss
@function map-merge-multiple($maps...) { ... }

// Example: combine spacers, negative spacers, and auto into a single values map
values: map-merge-multiple($spacers, $negative-spacers, (auto: auto))
```

#### `map-get-multiple($map, $values)`

```scss
@function map-get-multiple($map, $values) { ... }

// Example: extract only the flex and order utilities
$utilities: map-get-multiple(
  $utilities,
  ("flex", "flex-direction", "flex-grow", "order")
);
```

#### `map-get-nested($map, $nested-key)`

```scss
@function map-get-nested($map, $nested-key) { ... }

// Example: pull just the "font-size" value from each entry in $font-sizes
values: map-get-nested($font-sizes, "font-size")
// Returns: ("xs": clamp(...), "sm": clamp(...), ...)
```

#### `negativify-map($map)`

Turns a map into its negative variant by prefixing each key with `n` and negating the value. Keys equal to `0` are skipped. Use it when a custom utility needs negative values.

```scss
@function negativify-map($map) { ... }

// Example: generate negative values from part of the spacer scale
$custom-spacers: (0: 0, 1: .25rem, 2: .375rem, 3: .5rem);
$negative-spacers: negativify-map($custom-spacers);
// Returns: ("n1": -.25rem, "n2": -.375rem, "n3": -.5rem)
```

### Theme color values

The [`theme-color-values($key)`]([[docsref:/customize/theme]]) function in `scss/_theme.scss` extracts a specific sub-key from every entry in the `$theme-colors` map, returning a flat map of color names to values. Since each theme color is a nested map with sub-keys like `base`, `text`, `bg`, `border`, etc., this function lets you pull one of those sub-keys across all colors at once. It powers most of the color-related utilities in `_utilities.scss`:

```scss
// In _utilities.scss — generate .focus-ring-{color} classes
"focus-ring": (
  property: --focus-ring-color,
  class: focus-ring,
  values: theme-color-values("focus-ring"),
),

// Merge theme color backgrounds with semantic border tokens for .border-{color} classes
"border-color": (
  property: (
    "--border-color": null,
    "border-color": var(--border-color)
  ),
  class: border,
  values: map.merge(theme-color-values("bg"), $theme-borders),
),
```

### Theme opacity values

The [`theme-opacity-values($color-var, $opacities)`]([[docsref:/customize/theme]]) function in `scss/_theme.scss` generates a map of opacity variants for a CSS custom property using `color-mix()`. The `$opacities` argument defaults to `$util-opacity` (10 through 100 in steps of 10). At `100`, it returns the variable directly; for all other steps, it mixes the variable against `transparent`:

```scss
// In _utilities.scss — generate .border-{opacity} classes
"border-opacity": (
  class: border,
  property: border-color,
  values: theme-opacity-values(--border-color)
),

// Generate .fg-{opacity} classes
"fg-opacity": (
  class: fg,
  property: color,
  values: theme-opacity-values(--fg)
),
```

## Mixins

Our `scss/mixins/` directory has snippets of code that power Bootstrap and can also be used across your own project.

### Tokens

The `tokens()` mixin outputs a Sass map as CSS custom properties. Every component uses it to render its token map:

<ScssDocs name="mixin-tokens" file="scss/mixins/_tokens.scss" />

```scss
.alert {
  @include tokens($alert-tokens);
  // Outputs: --alert-padding-x: ...; --alert-padding-y: ...; etc.
}
```

### Color schemes

A shorthand mixin for the `prefers-color-scheme` media query is available with support for `light` and `dark` color schemes. See [the color modes documentation]([[docsref:/customize/color-modes]]) for information on our color mode mixin.

<ScssDocs name="mixin-color-scheme" file="scss/mixins/_color-scheme.scss" />

```scss
.custom-element {
  @include color-scheme(light) {
    // Insert light mode styles here
  }

  @include color-scheme(dark) {
    // Insert dark mode styles here
  }
}
```

### Theme classes

The `generate-theme-classes()` mixin loops over the `$theme-colors` map and outputs a `.theme-*` class for each color. Each class maps generic `--theme-*` custom properties to the color’s specific values, so components can reference `--theme-base`, `--theme-bg`, etc., and pick up the right palette from a parent `.theme-*` class. It also emits `.theme-reset`, which sets those tokens to `initial` so nested components use their own defaults again:

```scss
@include generate-theme-classes();
// Outputs:
// .theme-primary { --theme-base: var(--primary-base); --theme-bg: var(--primary-bg); ... }
// .theme-success { --theme-base: var(--success-base); --theme-bg: var(--success-bg); ... }
// .theme-reset { --theme-base: initial; --theme-bg: initial; ... }
// ...
```

<ScssDocs name="generate-theme-reset" file="scss/_theme.scss" />

### Mask icons

The `mask-icon()` mixin renders an SVG icon via a CSS [`mask`](https://developer.mozilla.org/en-US/docs/Web/CSS/mask) so the shape is painted with the element’s `background-color`. This lets an icon inherit the current text color, enabling automatic dark mode without a separate SVG. We use this for the [close button]([[docsref:/components/close-button/]]), [navbar toggler]([[docsref:/components/navbar/]]), [checkbox marks]([[docsref:/forms/checkbox/]]), [breadcrumb dividers]([[docsref:/components/breadcrumb/]]), [datepicker arrows]([[docsref:/forms/datepicker/]]), and [carousel controls]([[docsref:/components/carousel/]]).

Some form controls can’t use `mask` because they don’t support pseudo-elements and masking would clip the whole field. The `<select>` chevron and inputs using `.form-control-caret` are two examples, which keep separate light and dark `background-image` SVGs instead as non-masked background images.

<ScssDocs name="mask-icon-mixin" file="scss/mixins/_mask-icon.scss" />

Set `background-color` on the element yourself (the mixin only outputs the `mask-*` properties), then pass your icon as the mask image. Pass `null` for the icon when it’s applied conditionally, such as per state or direction.

```scss
.custom-icon {
  // Declare a custom CSS variable for the icon. This could be on the same
  // element, `:root`, or a parent element. We're using a custom × icon. Be
  // sure to wrap in `escape-svg()` as well.
  --custom-icon: #{escape-svg(url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path fill='none' stroke='black' stroke-linecap='round' stroke-width='2' d='m4 4 8 8m0-8-8 8'/></svg>"))};

  width: 1rem;
  height: 1rem;
  background-color: currentcolor;
  @include mask-icon($icon: var(--custom-icon));
}
```

---
title: Visually hidden
description: Use these helpers to visually hide elements but keep them accessible to assistive technologies.
aliases: "/docs/[[config:docs_version]]/helpers/screen-readers/"
---

Visually hide an element while still allowing it to be exposed to assistive technologies (such as screen readers) with `.visually-hidden`. Use `.visually-hidden-focusable` to visually hide an element by default, but to display it when it’s focused (e.g. by a keyboard-only user). `.visually-hidden-focusable` can also be applied to a container–thanks to `:focus-within`, the container will be displayed when any child element of the container receives focus.

<Example code={`<h2 class="visually-hidden">Title for screen readers</h2>
  <a class="visually-hidden-focusable" href="#content">Skip to main content</a>
  <div class="visually-hidden-focusable">A container with a <a href="#">focusable element</a>.</div>`} />

Both `visually-hidden` and `visually-hidden-focusable` can also be used as mixins.

```scss
// Usage as a mixin

.visually-hidden-title {
  @include visually-hidden;
}

.skip-navigation {
  @include visually-hidden-focusable;
}
```

---
title: Breakpoints
description: Breakpoints are customizable widths that determine how your responsive layout behaves across device or viewport sizes in Bootstrap.
aliases:
 - "/docs/[[config:docs_version]]/layout/"
 - "/docs/layout/"
 - "/layout/"
toc: true
---

## Core concepts

- **Breakpoints are the building blocks of responsive design.** Use them to control when your layout can be adapted at a particular viewport or device size.

- **Use media queries to architect your CSS by breakpoint.** Media queries are a feature of CSS that allow you to conditionally apply styles based on a set of browser and operating system parameters. We most commonly use `min-width` in our media queries.

- **Mobile first, responsive design is the goal.** Bootstrap’s CSS aims to apply the bare minimum of styles to make a layout work at the smallest breakpoint, and then layers on styles to adjust that design for larger devices. This optimizes your CSS, improves rendering time, and provides a great experience for your visitors.

## Available breakpoints

Bootstrap includes six default breakpoints, sometimes referred to as _grid tiers_, for building responsively. These breakpoints can be customized if you’re using our source Sass files.

<BsTable>
| Breakpoint | Class infix | Dimensions |
| --- | --- | --- |
| Extra small | <em>None</em> |&lt;576px |
| Small | `sm` | &ge;576px |
| Medium | `md` | &ge;768px |
| Large | `lg` | &ge;1024px |
| Extra large | `xl` | &ge;1280px |
| Extra extra large | `2xl` | &ge;1536px |
</BsTable>

Each breakpoint was chosen to comfortably hold containers whose widths are multiples of 12. Breakpoints are also representative of a subset of common device sizes and viewport dimensions—they don’t specifically target every use case or device. Instead, the ranges provide a strong and consistent foundation to build on for nearly any device.

These breakpoints are customizable via Sass—you’ll find them in a Sass map in our `_config.scss` stylesheet.

<ScssDocs name="breakpoints" file="scss/_config.scss" />

For more information and examples on how to modify our Sass maps and variables, please refer to [the CSS section of the Grid documentation]([[docsref:/layout/grid#css]]).

## Media queries

Since Bootstrap is developed to be mobile first, we use a handful of [media queries](https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_media_queries/Using_media_queries) to create sensible breakpoints for our layouts and interfaces. These breakpoints are mostly based on minimum viewport widths and allow us to scale up elements as the viewport changes.

### Min-width

Bootstrap primarily uses the following media query ranges—or breakpoints—in our source Sass files for our layout, grid system, and components.

```scss
// Source mixins

// No media query necessary for xs breakpoint as it’s effectively `@media (min-width: 0) { ... }`
@include media-breakpoint-up(sm) { ... }
@include media-breakpoint-up(md) { ... }
@include media-breakpoint-up(lg) { ... }
@include media-breakpoint-up(xl) { ... }
@include media-breakpoint-up(2xl) { ... }

// Usage

// Example: Hide starting at `min-width: 0`, and then show at the `sm` breakpoint
.custom-class {
  display: none;
}
@include media-breakpoint-up(sm) {
  .custom-class {
    display: block;
  }
}
```

These Sass mixins translate in our compiled CSS using the values declared in our Sass variables. For example:

```scss
// X-Small devices (portrait phones, less than 576px)
// No media query for `xs` since this is the default in Bootstrap

// Small devices (landscape phones, 576px and up)
@media (width >= 576px) { ... }

// Medium devices (tablets, 768px and up)
@media (width >= 768px) { ... }

// Large devices (desktops, 1024px and up)
@media (width >= 1024px) { ... }

// X-Large devices (large desktops, 1280px and up)
@media (width >= 1280px) { ... }

// XX-Large devices (larger desktops, 1536px and up)
@media (width >= 1536px) { ... }
```

### Max-width

We occasionally use media queries that go in the other direction (the given screen size _or smaller_):

```scss
// No media query necessary for xs breakpoint as it’s effectively `@media (max-width: 0) { ... }`
@include media-breakpoint-down(sm) { ... }
@include media-breakpoint-down(md) { ... }
@include media-breakpoint-down(lg) { ... }
@include media-breakpoint-down(xl) { ... }
@include media-breakpoint-down(2xl) { ... }

// Example: Style from medium breakpoint and down
@include media-breakpoint-down(md) {
  .custom-class {
    display: block;
  }
}
```

These mixins use the breakpoint values to create `max-width` media queries using modern range syntax. For example:

```scss
// `xs` returns only a ruleset and no media query
// ... { ... }

// `sm` applies to x-small devices (portrait phones, less than 576px)
@media (width < 576px) { ... }

// `md` applies to small devices (landscape phones, less than 768px)
@media (width < 768px) { ... }

// `lg` applies to medium devices (tablets, less than 1024px)
@media (width < 1024px) { ... }

// `xl` applies to large devices (desktops, less than 1280px)
@media (width < 1280px) { ... }

// `2xl` applies to x-large devices (large desktops, less than 1536px)
@media (width < 1536px) { ... }
```

### Single breakpoint

There are also media queries and mixins for targeting a single segment of screen sizes using the minimum and maximum breakpoint widths.

```scss
@include media-breakpoint-only(xs) { ... }
@include media-breakpoint-only(sm) { ... }
@include media-breakpoint-only(md) { ... }
@include media-breakpoint-only(lg) { ... }
@include media-breakpoint-only(xl) { ... }
@include media-breakpoint-only(2xl) { ... }
```

For example the `@include media-breakpoint-only(md) { ... }` will result in :

```scss
@media (width >= 768px) and (width < 1024px) { ... }
```

### Between breakpoints

Similarly, media queries may span multiple breakpoint widths:

```scss
@include media-breakpoint-between(md, xl) { ... }
```

Which results in:

```scss
// Example
// Apply styles starting from medium devices and up to extra large devices
@media (width >= 768px) and (width < 1280px) { ... }
```

## Container queries

In addition to viewport-based media queries, Bootstrap uses [container queries](https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_containment/Container_queries) for certain components. Container queries allow elements to respond to the size of a parent element rather than the viewport, enabling more flexible and modular responsive behavior.

Container queries use the same breakpoint values as viewport media queries.

### Usage in Bootstrap

The following components use container queries:

- **[Navbar]([[docsref:/components/navbar]])** — Uses container queries for its responsive expand behavior. The `.navbar` element is set as a query container, and the `.*:navbar-expand` classes use `@container` queries instead of `@media` queries. This means the navbar responds to its own width rather than the viewport width, making it more adaptable when placed in different layout contexts (e.g., within a sidebar or constrained container).

- **[Stepper]([[docsref:/components/stepper]])** — The `.stepper-overflow` wrapper uses `container-type: inline-size` to establish a containment context for the horizontally scrolling stepper pattern.

- **[List group]([[docsref:/components/list-group]])** — The `.*:list-group-horizontal` classes use `@container` queries so the list group switches between vertical and horizontal layouts based on the width of its query container rather than the viewport.

- **[Card]([[docsref:/components/card]])** — The `.card-group` layout uses an `@container` query to attach cards into equal-width columns based on the width of its query container rather than the viewport.

Here’s how the navbar implements container queries:

```scss
// The navbar is defined as a query container
.navbar {
  container-type: inline-size;
}

// Responsive classes use container queries
.lg\:navbar-expand {
  @container (min-width: 1024px) {
    // Expanded navbar styles...
  }
}
```

### Setting a container

Use the `set-container()` mixin to establish an element as a query container:

```scss
// Default: inline-size containment
.my-component {
  @include set-container();
  // Output: container-type: inline-size;
}

// With explicit type
.my-component {
  @include set-container(size);
  // Output: container-type: size;
}

// With a name (uses shorthand property)
.my-component {
  @include set-container(inline-size, sidebar);
  // Output: container: sidebar / inline-size;
}
```

### Container query mixins

Similar to the `media-breakpoint-*` mixins for viewport-based media queries, Bootstrap provides container query mixins that use the same breakpoint values and range syntax.

#### Min-width

Use `container-breakpoint-up()` to apply styles when the container is at least the given breakpoint width:

```scss
.my-component {
  @include set-container();
}

.my-component-child {
  // …

  @include container-breakpoint-up(md) {
    // Styles for when container is at least 768px wide
  }

  @include container-breakpoint-up(lg) {
    // Styles for when container is at least 1024px wide
  }
}
```

These mixins use the same modern range syntax as media queries. For example:

```scss
@container (width >= 768px) { ... }
@container (width >= 1024px) { ... }
```

#### Max-width

Use `container-breakpoint-down()` to apply styles when the container is narrower than the given breakpoint:

```scss
// Sass usage
@include container-breakpoint-down(lg) { ... }

// Compiled CSS
@container (width < 1024px) { ... }
```

#### Single breakpoint

Use `container-breakpoint-only()` to target a single breakpoint range:

```scss
// Sass usage
@include container-breakpoint-only(md) { ... }

// Compiled CSS
@container (width >= 768px) and (width < 1024px) { ... }
```

#### Between breakpoints

Use `container-breakpoint-between()` to span multiple breakpoint widths:

```scss
// Sass usage
@include container-breakpoint-between(md, xl) { ... }

// Compiled CSS
@container (width >= 768px) and (width < 1280px) { ... }
```

### Named containers

All container query mixins accept an optional container name parameter for querying a specific ancestor container. This is useful when you have nested containers:

```scss
.sidebar {
  @include set-container(inline-size, sidebar);
}

.main-content {
  @include set-container(inline-size, main);
}

// Query the sidebar container specifically, even if nested inside main
.widget {
  @include container-breakpoint-up(md, sidebar) {
    // …
  }
}
```

The compiled output includes the container name:

```scss
@container sidebar (width >= 768px) { ... }
```

---
title: Utility API
description: The utility API is a Sass-based tool to generate utility classes.
aliases:
 - "/docs/[[config:docs_version]]/utilities/"
 - "/docs/utilities/"
 - "/utilities/"
toc: true
---

Bootstrap utilities are generated with our utility API and can be used to modify or extend our default set of utility classes via Sass. Our utility API is based on a series of Sass maps and functions for generating families of classes with various options. If you’re unfamiliar with Sass maps, read up on the [official Sass docs](https://sass-lang.com/documentation/values/maps/) to get started.

The `$utilities` map contains all our utilities and is later merged with your custom `$utilities` map, if present. The utility map contains a keyed list of utility groups which accept the following options:

<BsTable class="table table-utilities">
| Option | Type | Default&nbsp;value | Description |
| --- | --- | --- | --- |
| [`property`](#property) | **Required** | – | Name of the property. Can be a string, a space-separated list of strings (e.g., horizontal paddings or margins), or a **map** of property-to-default-value pairs (see [Property-Value Mapping](#property-value-mapping)). |
| [`values`](#values) | **Required** | – | List of values, or a map if you don’t want the class name to be the same as the value. If `null` is used as map key, `class` is not prepended to the class name. |
| [`selector`](#selector) | Optional | `class` | Type of CSS selector in the generated CSS ruleset. Can be `class`, `attr-starts`, or `attr-includes`. |
| [`child-selector`](#child-selector) | Optional | null | A child/descendant selector appended to the utility’s selector, wrapped in `:where()` for zero specificity. Use to target children instead of the element itself. |
| [`class`](#class) | Optional | null | Name of the generated class. If not provided and `property` is an array of strings, `class` will default to the first element of the `property` array. If not provided and `property` is a string, the `values` keys are used for the `class` names. |
| [`variables`](#variables) | Optional | null | List or map of CSS custom properties to generate within each utility class. When a list, each variable receives the utility value. When a map, the provided static values are used. |
| [`state`](#states) | Optional | null | List of pseudo-class variants (e.g., `:hover` or `:focus`) to generate as prefix-style classes. |
| [`responsive`](#responsive) | Optional | `false` | Boolean indicating if responsive classes should be generated. |
| [`important`](#importance) | Optional | `false` | Boolean indicating if `!important` should be added to the utility’s CSS rules. |
| [`print`](#print) | Optional | `false` | Boolean indicating if print classes need to be generated. |
| [`dark`](#dark) | Optional | `false` | Boolean indicating if `dark:` prefixed classes should be generated, scoped to `@media (prefers-color-scheme: dark)`. |
| [`enabled`](#enabled) | Optional | `true` | Set to `false` to suppress output for a utility while keeping its definition in the `$utilities` map. |
</BsTable>

## API explained

All utility variables are added to the `$utilities` variable within our `_utilities.scss` stylesheet, which is a giant, nested Sass map. Each group of utility classes are generated from a block that looks something like this:

```scss
$utilities: (
  "opacity": (
    property: opacity,
    values: (
      0: 0,
      25: .25,
      50: .5,
      75: .75,
      100: 1,
    )
  )
);
```

Which outputs the following:

```css
.opacity-0 { opacity: 0; }
.opacity-25 { opacity: .25; }
.opacity-50 { opacity: .5; }
.opacity-75 { opacity: .75; }
.opacity-100 { opacity: 1; }
```

### `property`

<div class="badge badge-subtle theme-danger fs-sm fw-normal align-self-start">Required</div>

The `property` key must be set for any utility, and it must contain a valid CSS property. This property is used in the generated utility’s ruleset. When the `class` key is omitted, it also serves as the default class name. Consider the `text-decoration` utility:

```scss
$utilities: (
  "text-decoration": (
    property: text-decoration,
    values: none underline line-through
  )
);
```

Output:

```css
.text-decoration-none { text-decoration: none; }
.text-decoration-underline { text-decoration: underline; }
.text-decoration-line-through { text-decoration: line-through; }
```

#### Property value mapping

The `property` key also accepts a **map** of CSS property names to default values. This lets a single utility class set multiple properties at once, and lets values override individual properties when the value is itself a map.

When a property's default value in the map is `null`, the utility value is used directly for that property. When a default value is set, it is used unless the utility's value map contains a matching key.

A common pattern is pairing a CSS custom property (which receives the utility value) with a regular property that references it:

```scss
$utilities: (
  "bg-color": (
    property: (
      "--bg": null,
      "background-color": var(--bg)
    ),
    class: bg,
    values: (
      primary: var(--blue-500),
      danger:  var(--red-500),
    )
  )
);
```

Output:

```css
.bg-primary { --bs-bg: var(--bs-blue-500); background-color: var(--bs-bg); }
.bg-danger  { --bs-bg: var(--bs-red-500);  background-color: var(--bs-bg); }
```

<Callout type="info">
  Source CSS variables are used without a `--bs-` prefix, which is added in our compiled CSS with [our PostCSS plugin](https://github.com/twbs/postcss-prefix-custom-properties).
</Callout>

You can also set per-value overrides. When `values` contains a nested map whose keys match properties in the `property` map, those values are used for the matching property:

```scss
$utilities: (
  "text-size": (
    property: (
      "font-size":   1rem,
      "line-height": 1.5
    ),
    class: text,
    values: (
      "sm": ("font-size": .875rem, "line-height": 1.25),
      "lg": ("font-size": 1.25rem, "line-height": 1.75),
    )
  )
);
```

Output:

```css
.text-sm { font-size: .875rem; line-height: 1.25; }
.text-lg { font-size: 1.25rem; line-height: 1.75; }
```

### `values`

<div class="badge badge-subtle theme-danger fs-sm fw-normal align-self-start">Required</div>

Use the `values` key to specify which values for the specified `property` should be used in the generated class names and rules. Can be a list or map (set in the utilities or in a Sass variable).

As a list, like with [`text-decoration` utilities]([[docsref:/utilities/text-decoration]]):

```scss
values: none underline line-through
```

As a map, like with [`opacity` utilities]([[docsref:/utilities/opacity]]):

```scss
values: (
  0: 0,
  25: .25,
  50: .5,
  75: .75,
  100: 1,
)
```

As a Sass variable that sets the list or map, as in our [`position` utilities]([[docsref:/utilities/position]]):

```scss
values: $position-values
```

### `selector`

<BsTable>
| Option | Description |
| --- | --- |
| No selector | Defaults to `"class"` |
| `"class"` | Matches elements with a class that matches the specified value |
| `"attr-starts"` | Matches elements with a class that starts with a string |
| `"attr-includes"` | Matches elements with a class that includes a string |
</BsTable>

Use the `selector` option to change the CSS selector used in the generated CSS ruleset. The default option is to generate a class selector. When using an attribute selector—either `attr-starts` or `attr-includes`—**the `class` option is required**. We use these internally to simplify the construction of other utilities.

For attribute selectors, you’ll most likely want the `attr-includes` as the starting attribute selector in CSS applies to the entire string of classes in an attribute’s value. For example, `[class^="name"]` would not match `class="example name"`.

As an example, to change from `.ratio-*` to `[class*="ratio-"]`:

```scss
$utilities: (
  // Create an attribute selector utility
  "aspect-ratio-attr": (
    selector: "attr-includes",
    class: "ratio-",
    property: aspect-ratio,
    values: var(--ratio),
  ),
  // Create a CSS variable utility that matches the attribute selector utility
  "aspect-ratio": (
    property: --ratio,
    class: ratio,
    values: $aspect-ratios
  ),
);
```

Note that the `--ratio` custom property will automatically be prefixed to `--bs-ratio` in the compiled CSS via PostCSS.

Which outputs the following:

```css
[class*="ratio-"] { aspect-ratio: var(--bs-ratio); }
.ratio-auto { --bs-ratio: auto; }
.ratio-1x1 { --bs-ratio: 1 / 1; }
.ratio-4x3 { --bs-ratio: 4 / 3; }
.ratio-16x9 { --bs-ratio: 16 / 9; }
.ratio-21x9 { --bs-ratio: 21 / 9; }
```

### `child-selector`

Use the `child-selector` option to apply a CSS property to children of the element with the utility class rather than the element itself. The generated selector is wrapped in `:where()` for zero specificity, making it easy to override. This powers our built-in [`space-x/y`]([[docsref:/utilities/space]]) and [`divide-x/y`]([[docsref:/utilities/divide]]) utilities.

For example, our `space-x` utility uses `child-selector` to add horizontal spacing between direct children:

```scss
$utilities: (
  "space-x": (
    property: margin-inline-end,
    class: space-x,
    child-selector: "> :not(:last-child)",
    values: $spacers
  )
);
```

Output includes:

```css
:where(.space-x-1 > :not(:last-child)) { margin-inline-end: .25rem; }
:where(.space-x-2 > :not(:last-child)) { margin-inline-end: .375rem; }
:where(.space-x-3 > :not(:last-child)) { margin-inline-end: .5rem; }
/* ...through .space-x-12 */
```

The `child-selector` value can be any valid CSS selector. For example, you could create a striped row utility using `:nth-child()`:

```scss
$utilities: (
  "striped-bg": (
    property: background-color,
    class: striped,
    child-selector: "> :nth-child(odd)",
    values: (
      null: var(--bs-bg-1),
    )
  )
);
```

Output:

```css
:where(.striped > :nth-child(odd)) { background-color: var(--bs-bg-1); }
```

Or target all direct children with `> *`:

```scss
$utilities: (
  "child-rounded": (
    property: border-radius,
    class: child-rounded,
    child-selector: "> *",
    values: (
      null: var(--bs-border-radius),
      0: 0,
    )
  )
);
```

Output:

```css
:where(.child-rounded > *) { border-radius: var(--bs-border-radius); }
:where(.child-rounded-0 > *) { border-radius: 0; }
```

### `class`

Use the `class` option to change the class prefix used in the compiled CSS. For example, to change from `.opacity-*` to `.o-*`:

```scss
$utilities: (
  "opacity": (
    property: opacity,
    class: o,
    values: (
      0: 0,
      25: .25,
      50: .5,
      75: .75,
      100: 1,
    )
  )
);
```

Output:

```css
.o-0 { opacity: 0; }
.o-25 { opacity: .25; }
.o-50 { opacity: .5; }
.o-75 { opacity: .75; }
.o-100 { opacity: 1; }
```

If `class: null`, generates classes for each of the `values` keys:

```scss
$utilities: (
  "visibility": (
    property: visibility,
    class: null,
    values: (
      visible: visible,
      invisible: hidden,
    )
  )
);
```

Output:

```css
.visible { visibility: visible; }
.invisible { visibility: hidden; }
```

### Variables

Use the `variables` option to generate CSS custom properties within each utility class’s ruleset. The value can be either a **list** or a **map**.

When `variables` is a **list**, each variable receives the current utility value:

```scss
$utilities: (
  "link-opacity": (
    property: color,
    class: link,
    variables: link-color,
    values: (
      10: 10%,
      50: 50%,
      100: 100%,
    )
  ),
);
```

Output:

```css
.link-10 { --bs-link-color: 10%; color: 10%; }
.link-50 { --bs-link-color: 50%; color: 50%; }
.link-100 { --bs-link-color: 100%; color: 100%; }
```

When `variables` is a **map**, the provided static values are used on every generated class:

```scss
$utilities: (
  "link-underline": (
    property: text-decoration-color,
    class: link-underline,
    variables: (
      "link-underline-opacity": 1
    ),
    values: (...)
  )
);
```

Output:

```css
.link-underline-primary {
  --bs-link-underline-opacity: 1;
  text-decoration-color: ...;
}
```

### States

Use the `state` option to generate pseudo-class variations. Example pseudo-classes are `:hover` and `:focus`. When a list of states are provided, classnames are created for that pseudo-class with a prefix-style syntax matching the responsive prefix pattern. For example, to change opacity on hover, add `state: hover` and you’ll get `.hover\:opacity:hover` in your compiled CSS.

Need multiple pseudo-classes? Use a space-separated list of states: `state: hover focus`.

```scss
$utilities: (
  "opacity": (
    property: opacity,
    class: opacity,
    state: hover,
    values: (
      0: 0,
      25: .25,
      50: .5,
      75: .75,
      100: 1,
    )
  )
);
```

Output:

```css
.hover\:opacity-0:hover { opacity: 0; }
.hover\:opacity-25:hover { opacity: .25; }
.hover\:opacity-50:hover { opacity: .5; }
.hover\:opacity-75:hover { opacity: .75; }
.hover\:opacity-100:hover { opacity: 1; }
```

### Responsive

Add the `responsive` boolean to generate responsive utilities (e.g., `.md\:opacity-25`) across [all breakpoints]([[docsref:/layout/breakpoints]]).

```scss
$utilities: (
  "opacity": (
    property: opacity,
    responsive: true,
    values: (
      0: 0,
      25: .25,
      50: .5,
      75: .75,
      100: 1,
    )
  )
);
```

Output:

```css
.opacity-0 { opacity: 0; }
.opacity-25 { opacity: .25; }
.opacity-50 { opacity: .5; }
.opacity-75 { opacity: .75; }
.opacity-100 { opacity: 1; }

@media (min-width: 576px) {
  .sm\:opacity-0 { opacity: 0; }
  .sm\:opacity-25 { opacity: .25; }
  .sm\:opacity-50 { opacity: .5; }
  .sm\:opacity-75 { opacity: .75; }
  .sm\:opacity-100 { opacity: 1; }
}

@media (min-width: 768px) {
  .md\:opacity-0 { opacity: 0; }
  .md\:opacity-25 { opacity: .25; }
  .md\:opacity-50 { opacity: .5; }
  .md\:opacity-75 { opacity: .75; }
  .md\:opacity-100 { opacity: 1; }
}

@media (min-width: 1024px) {
  .lg\:opacity-0 { opacity: 0; }
  .lg\:opacity-25 { opacity: .25; }
  .lg\:opacity-50 { opacity: .5; }
  .lg\:opacity-75 { opacity: .75; }
  .lg\:opacity-100 { opacity: 1; }
}

@media (min-width: 1280px) {
  .xl\:opacity-0 { opacity: 0; }
  .xl\:opacity-25 { opacity: .25; }
  .xl\:opacity-50 { opacity: .5; }
  .xl\:opacity-75 { opacity: .75; }
  .xl\:opacity-100 { opacity: 1; }
}

@media (min-width: 1536px) {
  .\32 xl\:opacity-0 { opacity: 0; }
  .\32 xl\:opacity-25 { opacity: .25; }
  .\32 xl\:opacity-50 { opacity: .5; }
  .\32 xl\:opacity-75 { opacity: .75; }
  .\32 xl\:opacity-100 { opacity: 1; }
}
```

### Print

Enabling the `print` option will **also** generate utility classes for print, which are only applied within the `@media print { ... }` media query.

```scss
$utilities: (
  "opacity": (
    property: opacity,
    print: true,
    values: (
      0: 0,
      25: .25,
      50: .5,
      75: .75,
      100: 1,
    )
  )
);
```

Output:

```css
.opacity-0 { opacity: 0; }
.opacity-25 { opacity: .25; }
.opacity-50 { opacity: .5; }
.opacity-75 { opacity: .75; }
.opacity-100 { opacity: 1; }

@media print {
  .print\:opacity-0 { opacity: 0; }
  .print\:opacity-25 { opacity: .25; }
  .print\:opacity-50 { opacity: .5; }
  .print\:opacity-75 { opacity: .75; }
  .print\:opacity-100 { opacity: 1; }
}
```

### Dark

Enabling the `dark` option generates `dark:` prefixed classes scoped to `@media (prefers-color-scheme: dark)`. This follows the same prefix convention as responsive and print utilities.

```scss
$utilities: (
  "bg-color": (
    property: background-color,
    class: bg,
    dark: true,
    values: (
      white: #fff,
      black: #000,
    )
  )
);
```

Output:

```css
.bg-white { background-color: #fff; }
.bg-black { background-color: #000; }

@media (prefers-color-scheme: dark) {
  .dark\:bg-white { background-color: #fff; }
  .dark\:bg-black { background-color: #000; }
}
```

### Enabled

Set `enabled: false` to suppress output for a utility without removing it from the `$utilities` map. This is useful when you want to keep the utility's definition available for reference or downstream `map.get()` calls, but don't want it to emit any CSS. See [Using the API](#using-the-api) for the load order this example needs.

```scss
// _my-utilities.scss
@use "sass:map";
@use "bootstrap/scss/config" as *;
@use "bootstrap/scss/utilities";

$utilities: map.merge(
  $utilities,
  (
    "float": map.merge(
      map.get($utilities, "float"),
      (enabled: false),
    ),
  )
);
```

## Importance

Utilities generated by the API no longer include `!important` by default in v6. This is because we now use CSS layers to ensure utilities override components and modifier classes as intended. You can enable `!important` on a per-utility basis by setting the `important` option to `true`.

```scss
$utilities: (
  "opacity": (
    property: opacity,
    important: true,
    values: (
      0: 0,
      25: .25,
      50: .5,
      75: .75,
      100: 1,
    )
  )
);
```

This will generate utilities with `!important`:

```css
.opacity-0 { opacity: 0 !important; }
.opacity-25 { opacity: .25 !important; }
.opacity-50 { opacity: .5 !important; }
.opacity-75 { opacity: .75 !important; }
.opacity-100 { opacity: 1 !important; }
```

## Using the API

Now that you’re familiar with how the utilities API works, learn how to add your own custom classes and modify our default utilities.

The examples below use two patterns. Pick the pattern that matches your change.

- **One file**—Configure `$utilities` when you load `bootstrap/scss/bootstrap`. Use this pattern to add a utility, to replace a utility, or to remove a utility.
- **Two files**—Put a `map.merge()` call in a partial. Then load the partial before `bootstrap/scss/bootstrap`. Use this pattern when your change must read the default definition. Examples are a new value, a new class prefix, or new responsive variants on a group you keep.

The one-file pattern needs one `@use` rule:

```scss
// my-bootstrap.scss
@use "bootstrap/scss/bootstrap" with (
  $utilities: (
    // Your utility groups go here
  )
);
```

Bootstrap merges your map with `map.merge()`. This merge is shallow. Your utility group replaces the whole default group with the same key. Supply the `property` and `values` keys in every group that emits CSS.

Sass cannot read a module and configure the same module in one file. Some changes therefore need the two-file pattern. The `bootstrap/scss/config` module declares `$utilities`. The `bootstrap/scss/utilities` module fills it with the default definitions. Your partial loads both modules. Then it writes the new map back to the config module.

The partial loads the config module with `as *`. This avoids a namespace prefix, so you can reference `$utilities` directly. An assignment to `$utilities` then writes back to the config module.

For a utility-only build, load `bootstrap/scss/utilities` and then `bootstrap/scss/utilities/api`. The API module emits the utility classes and nothing else.

```scss
// my-bootstrap-utilities.scss
@use "bootstrap/scss/utilities" with (
  $utilities: (
    // Your utility groups go here
  )
);
@use "bootstrap/scss/utilities/api";
```

### Override utilities

Override an existing utility with the same key. Pass the new definition in the `$utilities` configuration when you load Bootstrap. For example, take our existing overflow utility class definition:

<ScssDocs name="utils-overflow" file="scss/_utilities.scss" />

If you want to make those responsive, and adjust the values used, you can do this:

```scss
// my-bootstrap.scss
@use "bootstrap/scss/bootstrap" with (
  $utilities: (
    "overflow": (
      property: overflow,
      responsive: true,
      values: visible hidden scroll auto,
    ),
  )
);
```

Your group replaces the default group. Keep the `property` key, or the build stops with an error.

### Add utilities

Add a new utility with the `$utilities` configuration. Bootstrap merges your map on top of its defaults, so supply only the new utilities.

```scss
// my-bootstrap.scss
@use "bootstrap/scss/bootstrap" with (
  $utilities: (
    "cursor": (
      property: cursor,
      class: cursor,
      responsive: true,
      values: auto pointer grab,
    ),
  )
);
```

### Modify utilities

Modify an existing utility with `map.get()` and `map.merge()`. This change reads the default definition, so it needs the two-file pattern. In the example below, we’re adding an additional value to the `width` utilities:

```scss
// _my-utilities.scss
@use "sass:map";
@use "bootstrap/scss/config" as *;
// Fills `$utilities` with the default definitions
@use "bootstrap/scss/utilities";

$utilities: map.merge(
  $utilities,
  (
    "width": map.merge(
      map.get($utilities, "width"),
      (
        values: map.merge(
          map.get(map.get($utilities, "width"), "values"),
          (20: 20%),
        ),
      ),
    ),
  )
);
```

Load your partial first. Then load Bootstrap:

```scss
// my-bootstrap.scss
@use "my-utilities";
@use "bootstrap/scss/bootstrap";
```

#### Enable responsive

You can enable responsive classes for an existing set of utilities that are not currently responsive by default. This change keeps the default definition, so it needs the two-file pattern. For example, to make the `border` classes responsive:

```scss
// _my-utilities.scss
@use "sass:map";
@use "bootstrap/scss/config" as *;
@use "bootstrap/scss/utilities";

$utilities: map.merge(
  $utilities,
  (
    "border": map.merge(
      map.get($utilities, "border"),
      (responsive: true),
    ),
  )
);
```

Load this partial before `bootstrap/scss/bootstrap`, as shown above. You can also restate the whole group with the one-file pattern. See [Override utilities](#override-utilities).

This will now generate responsive variations of `.border` and `.border-0` for each breakpoint. Your generated CSS will look like this:

```css
.border { ... }
.border-0 { ... }

@media (min-width: 576px) {
  .sm\:border { ... }
  .sm\:border-0 { ... }
}

@media (min-width: 768px) {
  .md\:border { ... }
  .md\:border-0 { ... }
}

@media (min-width: 1024px) {
  .lg\:border { ... }
  .lg\:border-0 { ... }
}

@media (min-width: 1280px) {
  .xl\:border { ... }
  .xl\:border-0 { ... }
}

@media (min-width: 1536px) {
  .2xl\:border { ... }
  .2xl\:border-0 { ... }
}
```

#### Rename utilities

Missing v4 utilities, or used to another naming convention? The utilities API can be used to override the resulting `class` of a given utility. This change keeps the default definition, so it needs the two-file pattern. For example, to rename `.ms-*` utilities to oldish `.ml-*`:

```scss
// _my-utilities.scss
@use "sass:map";
@use "bootstrap/scss/config" as *;
@use "bootstrap/scss/utilities";

$utilities: map.merge(
  $utilities,
  (
    "margin-start": map.merge(
      map.get($utilities, "margin-start"),
      (class: ml),
    ),
  )
);
```

Load this partial before `bootstrap/scss/bootstrap`, as shown above.

### Remove utilities

Remove a default utility with the `$utilities` configuration. Set the group key to `null`.

```scss
// my-bootstrap.scss
@use "bootstrap/scss/bootstrap" with (
  $utilities: (
    "width": null,
    "float": null,
  )
);
```

You can also remove utilities with the [`map.remove()` Sass function](https://sass-lang.com/documentation/modules/map/#remove). This function reads the default map, so it needs the two-file pattern.

```scss
// _my-utilities.scss
@use "sass:map";
@use "bootstrap/scss/config" as *;
@use "bootstrap/scss/utilities";

$utilities: map.remove($utilities, "width", "float");
```

Load this partial before `bootstrap/scss/bootstrap`, as shown above.

### Add, remove, modify

You can add, remove, and modify many utilities all at once with the [`map.merge()` Sass function](https://sass-lang.com/documentation/modules/map/#merge). Here’s how you can combine the previous examples into one larger map.

```scss
// _my-utilities.scss
@use "sass:map";
@use "bootstrap/scss/config" as *;
@use "bootstrap/scss/utilities";

$utilities: map.merge(
  $utilities,
  (
    // Remove the `width` utility
    "width": null,
    // Make an existing utility responsive
    "border": map.merge(
      map.get($utilities, "border"),
      (responsive: true),
    ),
    // Add a new utility
    "cursor": (
      property: cursor,
      class: cursor,
      responsive: true,
      values: auto pointer grab,
    ),
  )
);
```

Then load the partial before Bootstrap:

```scss
// my-bootstrap.scss
@use "my-utilities";
@use "bootstrap/scss/bootstrap";
```
